INSERT INTO `abouts` (`id`, `title`, `date`, `description`, `image`, `user_id`, `status`, `created_at`, `updated_at`) VALUES
(1, 'আমাদের সম্পর্কে', '2022-01-01', '<p>সবুজে শ্যামলে ভরা আমাদের এদেশের বেশির ভাগ স্থানজুড়ে রয়েছে গ্রাম। আমাদের এ গ্রামগুলো যেন সবুজের লীলাভূমি। গ্রামের সবুজ প্রকৃতি যেকোনো মানুষের হৃদয়কে প্রশান্তিতে ভরে দেয়। গ্রামের শান্ত পরিবেশ মানুষের সকল ক্লান্তি দূর করে। গ্রামই এদেশের প্রাণ।&nbsp;<br />\r\n<br />\r\nউমনপুর গ্রাম সিলেট জেলার জৈন্তাপুর উপজেলার চিকনাগুল ইউনিয়নের ১নং ওয়ার্ডে অবস্থিত। গ্রামের বুকচিরে দক্ষিণ-উত্তরে সিলেট তামাবিল হাইওয়ে (এশিয়ান হাইওয়ে, সুপ্রাচীন সিলেট-সিলং মহাসড়ক) চলেগেছে। গ্রামের ভেতর দিয়ে অনেকগুলো প্রশস্ত কাঁচা/পাকা রাস্তা পূর্ব- পশ্চিম, উত্তর-দক্ষিণ দিকে ছড়িয়ে ছিটিয়ে রয়েছে। গ্রামের উত্তরে শিকার&nbsp; খাঁ ও হরিপুর গ্রাম, দক্ষিণে পানিছড়া , পূর্বে &nbsp;উমনপুর হাওর ও পশ্চিমে চিকনাগুল চা বাগিছা রয়েছে।</p>\r\n\r\n<p>উমনপুর গ্রামের জনসংখ্যা প্রায় তিন হাজারের মত। গ্রামে মুসলিম &ndash; হিন্দু উভয় সম্প্রদায়ের লোক পারস্পারিক সোহার্দ ও সম্প্রীতির মধ্যে বসবাস করছে। এদের মধ্যে গ্রামের শিক্ষার হার শতকরা ৮৫ ভাগ রয়েছে। গ্রামের উচ্চ শিক্ষিত লোকদের মধ্যে বিসিএস ক্যাডার, পিএইচডি ডিগ্রীদারি, ডাক্তার, ইঞ্জিনিয়ার, সামরিক বাহিনী, শিক্ষক ও সরকারী চাকুরিজীবি আছেন। এছাড়া শ্রমিক ও ব্যবসায়ীর সংখ্যাও কম নয়। গ্রামে রয়েছে কৃষক, জেলে, মাঝি সহ প্রভৃতি শ্রেনী ও পেষার লোক রয়েছে। গ্রামের অধিকাংশ মানুষ সহজ-সরল ও ধর্মভীরু। এই গ্রামে রেমিটেন্স যোদ্ধারা বিশ্বের বিভিন্ন দেশে ছড়িয়ে ছিটিয়ে রয়েছেন। গ্রামে বেশির ভাগ জনগোষ্ঠী মুসলিম সবাই পরস্পর মিলেমিশে বসবাস করেন।<br />\r\n&nbsp;</p>\r\n\r\n<p>উমনপুর গ্রামে একটি সরকারী প্রাথমিক বিদ্যালয়, একটি কওমি মাদ্রাসা, একটি সরকারী স্বাস্থ্য কপ্লেক্স, একটি স-মিল, দুইটি রাইস মিল, ৮নং গ্যাস কূপ, কয়েকটি ফিশ ফার্ম&nbsp; ও কয়েকটি&nbsp; পোল্ট্রি ফার্ম রয়েছে। উমনপুর গ্রামে একটি জামে মসজিদ, দুইটি পাঞ্জেগান মসজিদ ও একটি মন্দির রয়েছে। এছাড়া একটি আগ্রনী ব্যাংক এর একটি শাখা, ফিলিং ষ্টেশন ও একটি দুলভ বিল রয়েছে। সাংস্কৃতিবাবে আমাদের গ্রাম খুবী উন্নত। ধর্মীয় আচার অনুষ্ঠান ও বিভিন্ন সামাজিক অনুষ্ঠান আনুষ্ঠানিক ভাবে প্রতিপালন হয়ে থাকে। গ্রামে সবচেয়ে বড় উৎসব পল বাওয়া উৎসব । প্রতিবছর নিজস্য বিলে মহা-আনন্দে সকলের উপস্তিতিতে সকলে মিলে তা পালিত হয়। গ্রামের সকল হিন্দু - মুসলিম উভয় সপ্রদায়ের লোক&nbsp; মিলেমিশে সতস্ফুর্ত ভাবে অংশগ্রহণ করেন।</p>\r\n\r\n<p>মহান মুক্তিযুদ্ধে এ গ্রামের মানুষের অনেক অবদান রয়েছে। এ গ্রামের মানুষের সাহসী কথা ও বীরত্ব বাংলাদেশের প্রথম তৈল ও গ্যাস ক্ষেত্র (বর্তমান SGFL) পাকিস্তানি হানাদার বাহিনীর ধ্বংসযজ্ঞ হতে রক্ষা পেয়েছে। এই গ্রামের অনেক বীর সন্তান দেশ মাতৃকার জন্যে সংগ্রাম করেছেন কিন্তু মুক্তিযুদ্ধের সনদ সংগ্রহ করেন নাই।</p>\r\n\r\n<p>উমনপুর একটি ডিজিটাল, নেটিজেন গ্রাম। যেই গ্রামের একটি ওয়েবসাইট এবং ফেইসবুক, ইউটিউব ও গুগলের মত প্লাটফর্মে ছড়িয়ে ছিটিয়ে আছে। গুগল ম্যাপে উমনপুর গ্রাম অত্যন্ত সুন্দর ভাবে ফুটিয়ে তোলা হয়েছে যেমন - স্থান, স্থাপনা, রাস্তা, বাগান সহ যাবতীয় তথ্য সংযোক্ত করে। আমরা জানি যে গুগল ম্যাপ একজন মানুষকে অপরিচিত লোকেশনে কী পরিমাণ মাত্রায় সাহায্য করে তা বর্তমান সময়ে বলার অপেক্ষা রাখে না। &nbsp;</p>\r\n\r\n<p>উমনপুর গ্রামের প্রাকৃতিক দৃশ্য অতি মনোরম। গ্রামের আম, কাঁঠাল, লিচু, নারিকেল, বাঁশ বাগান, লেবু বাগান ও সুপারির বাগানগুলো সত্যিই নয়নাভিরাম। পাখিদের কলতান, সবুজ মাঠ, সোনালি ধানক্ষেত, বর্ষার পানিতে প্লাবিত জলাশয়&mdash; এসব দৃশ্য খুবই মনোমুগ্ধকর।</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>উমনপুর গ্রাম একটি আদর্শ গ্রাম। গ্রামের সকলের মধ্যে যথেষ্ট ভ্রাতৃত্ব ও মৈত্রীর ভাব বিদ্যমান।</p>', '1670936882Umonpur Logo Comparision.png', 1, 1, '2022-01-01 15:12:28', '2024-03-05 14:22:21'),
(2, 'উমনপুর আইটি', '2022-01-01', '<p>আইটির পূর্ণ নাম হল ইনফরমেশন টেকনোলজি। ইনফরমেশন টেকনোলজি (আইটি) হল কম্পিউটার বা অন্য কোন সংস্থার/ গ্রামের প্রসঙ্গে ডেটা বা তথ্য সংরক্ষণ, পুনরুদ্ধার, ট্রান্সমিট এবং ম্যানিপুলেশন। আইটি তথ্য এবং যোগাযোগ প্রযুক্তি একটি উপসেট।<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>শুভজাত্রাঃ</strong>&nbsp; উমনপুর গ্রামের একটি ওয়েবসাইট শুরু করার জন্য তরুন উদীয়মান আইটি বিষয়ে অভিজ্ঞ সায়েম আহমদ তার উপস্থাপনায় গ্রামের বৈঠকে ওয়েবসাইট শুরু করার সিদ্ধান্ত আনুমোদিত ও গৃহীত হয়। উমনপুর গ্রামের আইটি সমুদয় বিষয় তদারকি, দেখভাল ও নিয়ত্রন করার জন্যে নিম্নলিখিত সদস্যদের নিয়ে উমনপুর আইটি উপদেষ্টা কমিটি গঠন করা হয়। &nbsp;আইটি উপদেষ্টা মণ্ডলীগণ হলেন &ndash; মোঃ আব্দুল মোমেন, মোঃ মইনুল হোসেইন, মোঃ জালাল উদ্দিন, উসমান আলী, মোঃ মন্তাজ আলী, মোঃ সেলিম আহমদ, মোঃ খয়রুল ইসলাম, ফারুক আহমদ, মোঃ আহমেদ রহমান ও খালেদ আহমদ। এছাড়া উমনপুর আইটি পরিচালনা&nbsp; করার জন্যে আইটি পরিচালনা কমিটিও গঠন করা হয়। উপদেষ্টা, পরিচালনা ও গ্রামবাসীর মাধ্যমে উমনপুর গ্রামের অফিসিয়াল ওয়েবসাইটের আনুষ্টানিক ভাবে শুভযাত্রা হয় ২০২১ খ্রিষ্টাব্দ। আইটি বিষয়ে অভিজ্ঞ তরুণ সায়েম আহমদ তার মুখ্য ভূমিকায় উমনপুর আইটি পরিচালিত হবে।<br />\r\n<br />\r\n<strong>গুগলে&nbsp;উমনপুরঃ</strong> &nbsp;উমনপুর গ্রামে গুগল ম্যাপে গ্রামের গুরুত্বপূর্ণ স্থান, স্থাপনা, রাস্তা, বাগান সহ যাবতীয় তথ্য সংযোক্ত করার সিদ্ধান্ত গৃহীত হইলে দেখাযায় যে&nbsp; ইতিপুর্বে মোঃ হেলাল উদ্দীন পিতাঃ মোঃ জহির উদ্দীন ও সায়েম আহমদ পিতাঃ মোঃ ইদ্রিস আলী গুগল ম্যাপে গ্রামের নাম, সীমানা, জামে মসজিদ, বাস স্টপ সহ গ্রামের রাস্তা, দোকান, মসজিদ, মাদ্রাসা, স্কুল, দুলভ বিল, ফিশারি, জলাশয়, পোল্ট্রি ফার্ম ও স্বাস্থ্য কমপ্লেক্স এর মত &nbsp;উল্ল্যেখিত বিষয়গুলি সংযুক্ত করে রেখেছেন। এছাড়াও গুগল ইমেইল একাউন্ট এবং ভিডিও প্লাটফর্মের জন্যে ইউটিউবে এর জাত্রা শুরু হয়।</p>\r\n\r\n<p><strong>ওয়েবসাইটে উমনপুরঃ</strong> উপদেষ্টা কমিটির পরামর্শমত উমনপুর গ্রামের পরিপূর্ণ ওয়েবসাইট তৈরী করার জন্যে সায়েম আহমদ পিতাঃ ইদ্রিস আলী ওয়েবসাইটের ১ম ভার্সন ২০২১ইং, দ্বিতীয় ভার্সন ২০২২ইং ও তৃতীয় ভার্সন ২০২৩ইং &nbsp;নির্মাণ করেন। সকলের পরামর্শ মোতাবেক ওয়েবসাইটের অগ্রগতি অব্যাহত থাকবে।<br />\r\n<br />\r\n<strong>ফেইসবুকে উমনপুরঃ</strong> বর্তমান সময়ে অন্যতম সামাজিক যোগাযোগ মাধ্যম ফেইসবুকে উমনপুর গ্রামের উমনপুর গ্রুপ, উমনপুর&nbsp; পেইজ, উমনপুর একাদশ ক্রীড়া সংস্থ্যা পেইজ, উমনপুর একাদশ ক্রীড়া সংস্থ্যা গ্রুপ, &nbsp;উমনপুর সরকারি প্রাথমিক বিদ্যালয় পেইজ, মাহমুদিয়া মাযহারুল উলুম উমনপুর মাদ্রাসা পেইজ, ও চিকনাগুল স্বাস্থ্য কমপ্লেক্স পেইজ, নামে তৈরী করে প্রচারণা ও গ্রামের স্তির চিত্র ও ভিডিও চিত্রের মাধ্যমে উমনপুর গ্রামকে প্রদর্শন করা হচ্ছে।</p>\r\n\r\n<p><strong>উপদেষ্টা</strong><strong> </strong><strong>মন্দলীঃ </strong>বর্তমান <strong>&nbsp;</strong>১০জন সদস্য নিয়ে উমনপুর আইটি<strong>&nbsp; </strong>উপদেষ্টা মণ্ডলীগণ হলেন &ndash; মোঃ আব্দুল মোমেন, মোঃ মইনুল হোসেইন, মোঃ জালাল উদ্দিন, উসমান আলী, মোঃ মন্তাজ আলী, মোঃ সেলিম আহমদ, মোঃ খয়রুল ইসলাম, ফারুক আহমদ, মোঃ আহমেদ রহমান, খালেদ আহমদ।</p>\r\n\r\n<p><strong>উমনপুর আইটি পরিচালনা কমিটিঃ</strong> বর্তমানে&nbsp; ১৪জন সদস্য নিয়ে উমনপুর আইটি<strong> </strong>পরিচালনা হচ্ছে তাদের নাম হল &ndash; মোঃ আনোয়ার মাসুম, তাহির আলী আনসারী, সায়েম আহমদ, মাওলানা আব্দুর রহিম, আফজল আহমদ, নাসির আহমদ, নেওয়াজুর রাহমান, কবির আহমদ, আশিক আহমদ, জাহেদ আহমদ, জামান আহমদ, মন্তাজ আহমদ, মুক্তার আহমদ ও আক্তারুজ্জামান আশরাফ।</p>\r\n\r\n<p>ওয়েবসাইট একটি গ্রামের/ আঞ্চলের চলমান প্রতিশ্চবি এটি গ্রাম তথা অঞ্চলের পরিকল্পনা, বাস্তবায়ন ও উন্নয়নের মুখ্যভূমিকা পালন করে।</p>', '1679229070UP_IT_Logo6.png', 1, 0, '2022-01-01 15:12:58', '2023-07-06 23:37:09'),
(3, 'মাহমুদিয়া মায্হারুল উলূম উমনপুর', '2022-01-01', '<p><strong><em>সূচনা</em></strong>&nbsp;: মাদ্রাসা মানে ইসলামিক জ্ঞান অর্জনের শিক্ষালয়। মাদরাসা হলো সেসব শিক্ষাপ্রতিষ্ঠান যেখানে কুরআন , হাদিস ও ইসলামের বিভিন্ন বিষয়াদি শিক্ষা দেয়া হয় ।</p>\r\n\r\n<p><strong><em>বর্ণনা</em></strong>&nbsp;: সকল শিক্ষার পূর্বে&nbsp; ধর্মীয় শিক্ষাই আপরিহার্য, এরি বাস্তবতায় উমনপুর গ্রামবাসীর একটি মাদ্রাসা প্রতিষ্টার উদ্যেগ গ্রহণ করেন। এই মহতী উদ্যেগে সাড়া দিয়ে মাদ্রাসার জমি দাতা মোছাঃ মাহমুদা খাতুন, পিতাঃ আব্দুল বারী, স্বামীঃ আলহাজ মোছা মিয়া ------ শতক জমি দান করেন।&nbsp;জামেয়া মাহমুদিয়া মাযহারুল উলুম উমনপুর মাদ্রাসা জৈন্তাপুর উপজেলার ৬নং চিকনাগুল ইউনিয়নের উমনপুর গ্রামের এক অন্যতম ইসলামিক শিক্ষা প্রতিষ্টান। ইহা ০৪/০৪/১৮২৯ হিজরী, ২৯/১২/১৪১৪ বঙ্গাব্দ, ১১/০৮/২০০৮খ্রিষ্টাব্দ প্রতিষ্ঠিত হয়। মাদ্রাসায় পাঠদান শ্রেণী &nbsp;১) মক্তব চাহারম, ২)মক্তব ছুওম, ৩) মক্তব দুওম ৪) নুরানী প্রথম ৫) নুরানী শিশু ও ৬) হিফজ শাখা পর্যন্ত পাঠদান করা হয়। মাদ্রাসা দ্বিতীয় তলা ভবন,&nbsp; ছয়টি কক্ষ ও অজূখানা রয়েছে। মাদ্রাসায় বড় একটি মাঠ আছে। এসবই অত্যন্ত পরিকল্পিত ও সুসজ্জিত।<br />\r\n<br />\r\n<strong><em>শিক্ষার্থী - শিক্ষক সংখ্যা</em></strong>&nbsp;: মাদ্রাসায় অধ্যক্ষ ও সহকারী শিক্ষকসহ মোট ৭ জন শিক্ষক রয়েছেন । আর শিক্ষার্থীর সংখ্যা প্রায় ১২০ জন। মাদরাসায় শিক্ষকগণ সবাই উচ্চ শিক্ষায় শিক্ষিত । শিক্ষার্থীদের শিক্ষা - দীক্ষার পাশাপাশি আচার ব্যবহার , আদব , কায়দা শেখানোর বিষয়েও শিক্ষকগণ খুবই যত্নবান।</p>\r\n\r\n<p><strong>সহপাঠ কার্যক্রম</strong>&nbsp;: লেখাপড়ার পাশাপাশি আমাদের চরিত্র গঠন ও সুনাগরিক হিসেবে গড়ে তোলার জন্য আমাদের মাদরাসার শিক্ষকগণ সর্বদা সচেষ্ট । এছাড়া এখানে ইসলামিক নিয়ম নীতিমালা ইত্যাদির চর্চা হয়ে থাকে । তাছাড়া প্রতি বছর বার্ষিক জলসাকে কেন্দ্র করে শিশু শিক্ষা প্রদর্শণী আয়োজন করা হয়। &nbsp;</p>\r\n\r\n<p><strong>শিক্ষকগণের নামঃ</strong> &nbsp;</p>\r\n\r\n<p>১/ হযরত মাওলানা ফোরক্বান আলী কাসেমী মুহতামিম</p>\r\n\r\n<p>২/ হযরত মাওলানা তাজ উদ্দিন</p>\r\n\r\n<p>৩/ হযরত মাওলানা দেলওয়ার হোসাইন</p>\r\n\r\n<p>৪/ হযরত মাওলানা মিসবাহ উদ্দিন সুমন</p>\r\n\r\n<p>৫/হযরত মাওলানা কাওছার আহমদ (দুলু)</p>\r\n\r\n<p>৬/ হযরত মাওলানা রুহুল আমিন</p>\r\n\r\n<p>৭/ হাফিজ মাওলানা নুমানুল হক্ব।<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>এই দিনি শিক্ষাপ্রতিষ্টান হতে কোমলমতি শিশুরা অত্যান্ত আনন্দ ও আগ্রহের সাথে ইসলামি শিক্ষা আর্জন করছে। মাদ্রাসাটি ক্রমেই শিক্ষার মান ও শিক্ষার্থীর সংখ্যা দিন দিন বৃদ্ধি পাচ্ছে।&nbsp; লেখাপড়া, মাদ্রাসার অগ্রগতির সাপোর্ট&nbsp; হিসেবে গ্রামবাসী এবং সকল মুসল্লিয়ান কেরাম গণের সহযোগিতা ও দোয়া কামনা করি।</p>', '1674067197rsz-img-3297.webp', 1, 0, '2022-01-01 15:13:25', '2023-07-06 23:43:23'),
(4, 'উমনপুর সরকারী প্রাথমিক বিদ্যালয়', '2022-01-01', '<p>শিক্ষাই জাতির মেরুদন্ড। শিক্ষার জন্য চাই আদর্শ বিদ্যাপীঠ। এক সময় শিক্ষা ছিল মক্তব/ টোল ভিত্তিক। শিক্ষার্থী সেই সময় মক্তব/ টোল থেকেই গুরুর কাছ থেকে শিক্ষা লাভ করত। আদর্শ বিদ্যালয় এক-একটি টোল বিশেষ। এমনই একটি মহান টোল &nbsp;উমনপুর সরকারী প্রাথমিক বিদ্যালয়।</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>ইতিহাস</strong><strong> </strong><strong>ও</strong><strong> </strong><strong>ঐতিহ্যঃ</strong> উমনপুর সরকারী প্রাথমিক বিদ্যালয় জৈন্তাপুর উপজেলার ৬নং চিকনাগুল ইউনিয়নের উমনপুর গ্রামের এক অন্যতম শিক্ষা প্রতিষ্ঠান। ইহা ২০০০খ্রিঃ স্থাপিত হয়। স্থায়ী রেজিঃ-১১/০৮/২০১১খ্রিঃ এবং স্থায়ী জাতীয় করন-০৬/১০/২০১৩খ্রিঃ। যাত্রারম্ভে ইহা একটি বেসরকারী প্রতিষ্ঠান ছিল কিন্তু প্রবর্তীকালে সরকারি বিদ্যালয় পরিণত হয়। উমনপুর গ্রামবাসীর উদ্যোগে স্কুলের জমি ক্রয় ও স্কুল নির্মাণ&nbsp; হয় এবং গ্রামের অর্থায়নে শিক্ষকদের বেতন, বাতা প্রধান করা হয়। &nbsp;তৎকালীন এমপি জনাব ইমরান আহমদ&nbsp; উমনপুর সরকারী প্রাথমিক বিদ্যালয় এর শুভ উদ্বোধন করেন। পরবর্তিতে উমনপুর সরকারী প্রাথমিক বিদ্যালয় জাতীয়করণ হয়। জাতীয়করণ পর&nbsp; বিদ্যালয়ের নতুন ভবন নির্মাণ হয়।</p>\r\n\r\n<p><strong>সভাপতিগনের তালিকা ও কার্যকালঃ</strong></p>\r\n\r\n<p>১) জনাব আব্দুল মতিন মাষ্টার, পিতাঃ মছদ্দর আলী, মেয়াদ- ১৬/০৭/২০০০খ্রিঃ &ndash; ৩১/০৭/২০০২খ্রিঃ</p>\r\n\r\n<p>২) জনাব ফয়জুর রহমান চৌধুরী, পিতাঃ মাহমুদ আলী,&nbsp; মেয়াদ- ০১/০১/২০০৩ &ndash; ০৬/০২//২০১০খ্রিঃ</p>\r\n\r\n<p>৩) জনাব ফয়েজ উল্লাহ, পিতাঃ মোঃ হাবিবুর রহমান মেয়াদ- ০৬/০২/২০১০খ্রি &ndash; ৩১/১২/২০১২খ্রিঃ</p>\r\n\r\n<p>৪) জনাব আব্দুল মোমেন(মুতলিব), পিতা জায়ফর আলী, মেয়াদ- ০১/০১/২০১৩খ্রিঃ &ndash; ---/---/২০২৩খ্রিঃ।</p>\r\n\r\n<p>৫০ জনাব মন্তাজ আলী,&nbsp;পিতা -------------, মেয়াদ- ----/---/২০২৩খ্রিঃ -&nbsp;বর্তমান।</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>আবস্থানঃ</strong><strong> </strong>উমনপুর সরকারী প্রাথমিক বিদ্যালয় সিলেট জেলার জৈন্তাপুর উপজেলার ৬নং চিকনাগুল ইউনিয়নের ১নং ওয়ার্ডে গ্রামের মধ্যখানে এক সুন্দর ও মনোরম&nbsp;পরিবেশে আবস্থিত। বিদ্যালয়ের পাশদিয়ে এশিয়ান হাইওয়ে চলেগেছে।</p>\r\n\r\n<p><strong>অবকাঠামোঃ&nbsp;</strong>উমনপুর সরকারী প্রাথমিক বিদ্যালয় যাত্রালগ্নে টিনসেটের ঘর তৈরি করা হলেও ২০২০ - ২০২১খ্রীঃ অর্থ বছরে দুতলা বভনে প্রথম তলা নির্মাণ করা হয়। বভনের মধ্যে পাঁচটি শ্রেনী&nbsp;কক্ষ ও একটি অফিস কক্ষ রয়েছে। শিক্ষক শিক্ষার্থীদের ব্যবহারের জন্যে স্বাস্থ্য সম্মত অত্যাধুনিক একটি ওয়াশ ব্লক রয়েছে।<strong>&nbsp;</strong></p>\r\n\r\n<p><strong>সহপাঠ</strong><strong> </strong><strong>ক্রমিক</strong><strong> </strong><strong>কার্যাবলীঃ</strong><strong> </strong>প্রতিদিন যতা সময়ে সমাবেশের মধ্য দিয়েই স্কুল আরম্ভ হয়। সমাবেশে শিক্ষকরা বিভিন্ন বিষয়ের উপর বক্তৃতা দিয়ে থাকেন। তাছাড়া বিভিন্ন সময়ে নানারকম&nbsp; সামাজিক এবং ধার্মিক উৎসবে, বিশেষ বিশেষ দিবস খুব গুরুত্ব সহকারে পালন করা হয়। তাছাড়া বার্ষীক কীড়া প্রতিযোগিতা এবং মৌসুমি সকল খেলায় শিক্ষার্থীর অংশগ্রহন করে কৃতিত্বের সাথে সফলতা ও সুনাম অর্জন করে।&nbsp;<br />\r\n<br />\r\n<strong>ফলাফলঃ</strong> বিদ্যালয়ে শিক্ষার্থীরা সকল পরীক্ষায় কৃতিত্বের সহিত&nbsp; সফলতা&nbsp; লাভ করে।&nbsp;</p>\r\n\r\n<p>উপসংহারে বলা যায় যে উমনপুর সরকারী প্রাথমিক বিদ্যালয়ে শিক্ষার্থীরা পারস্পরিক সৌহার্দপূর্ণ&nbsp;পরিবেশে সকল বিষয়ে&nbsp; আনন্দের&nbsp; সাথে শিক্ষা অর্জন করে থাকে।&nbsp; এই বিদ্যালয়ে&nbsp; শিক্ষার্থীরা বাংলাদেশের সর্বোচ্চ বিদ্যাপিঠে লেখাপড়া করে কর্মক্ষেত্রে প্রতিভার স্বাক্ষর রাখছে। পরিশেষে বলা যায় উমনপুর সরকারী প্রাথমিক বিদ্যালয় একটি আদর্শ বিদ্যালয়।&nbsp;</p>', '1682335846rsz-img-2980.webp', 1, 0, '2022-01-01 15:13:48', '2023-07-07 19:16:26'),
(5, 'উমনপুর জামে মসজিদ', '2022-11-18', '<p>আনুমানিক ১৭০০ শতকের শেষের দিকে গ্রামের মুসলিম সম্প্রদায়ের উদ্দ্যেগে গ্রামের সবচেয়ে প্রাচীন প্রতিষ্ঠান উমনপুর জামে মসজিদ প্রতিষ্ঠা লাভ করে। প্রতিষ্ঠার পর প্রথম দিকে ইট সুরকীর ডালাই দিয়ে&nbsp; মসজিদ নির্মাণ করা হয়। সর্বশেষ ২০১২ সালের দিকে পুরাতন মসজিদ ভেঙ্গে ৪র্থ তলা ফাউন্ডেশন দিয়ে বর্তমান দৃষ্টিনন্দন প্রথম তলা মসজিদ নির্মাণ করা হয়। যার অর্থ গ্রামের ধর্ম প্রাণ&nbsp; মুসল্লি, দানশীল ব্যাক্তি বর্গ ও গ্রামের ফান্ডের অর্থের মাধ্যমে&nbsp; নির্মিত হয় উমনপুর জামে মসজিদ। এছাড়াও মসজিদে একটি আত্যাধুনিক ওয়াশ ব্লক আছে। যার অর্থ গ্রামের ফান্ড ও&nbsp; গ্রামের ধর্ম প্রাণ&nbsp; মুসল্লিদের অর্থায়নে নির্মিত হয়।</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>১৯৮৫ সালের পরে নিম্ন লিখিত ব্যাক্তি বর্গ উমনপুর জামে মসজিদের জমি দান করেছিলেন- (১)আজিজুর রহমান (২) সালামত উল্লাহ (৩) চান্দ মিয়া (৪) জামাল আব্দুন নাছের (৫) হাফিজ উমর আলী&nbsp; (৬) আজির উদ্দিন ও (৭) রফিক আহমদ। &nbsp;<br />\r\n&nbsp;</p>\r\n\r\n<p>মসজিদ নির্মাণ কমিটিঃ</p>\r\n\r\n<p>১। মোঃ ফয়েজ উল্যাহ পিতা মোঃ হাবিবুর রহমান।</p>\r\n\r\n<p>২। মোঃ আব্দুল হান্নান পিতা মোঃ মছদ্দর আলী।</p>\r\n\r\n<p>৩। মাহমুদ হোসেইন রব্বানী পিতা &nbsp;আলহাজ্ব ইছা মিয়া।</p>\r\n\r\n<p>৪। মোঃ মন্তাজ আলী পিতা &nbsp;মোঃ মছদ্দর আলী।</p>\r\n\r\n<p>৫। মোঃ খয়রুল ইসলাম পিতাঃ আলহাজ্ব ইউসুফ আলী।</p>', '1674067278rsz-img-2947.webp', 1, 0, '2022-01-01 15:14:20', '2023-07-06 23:22:39'),
(6, 'উমনপুর পাঞ্জেগানা মসজিদ', '2022-01-01', '<p>&nbsp;তথ্য হালনাগদ এর কাজ&nbsp; চলমান ... আমরা খুবী শিগ্রী তথ্য হালনাগদ করবো।&nbsp;</p>', '1675259557panjegana_img.webp', 1, 0, '2022-01-01 15:14:44', '2023-09-08 22:01:47'),
(7, 'দুলভ বিল উমনপুর', '2022-01-02', '<p>&nbsp;তথ্য হালনাগদ এর কাজ&nbsp; চলমান ... আমরা খুবী শিগ্রী তথ্য হালনাগদ করবো।&nbsp;</p>', '16740679431671018121.webp', 1, 0, '2022-01-02 13:36:43', '2023-09-08 22:02:00'),
(8, 'হাইওয়ে ফিলিং ষ্টেশন, উমনপুর।', '2022-01-02', '<p>&nbsp;তথ্য হালনাগদ এর কাজ&nbsp; চলমান ... আমরা খুবী শিগ্রী তথ্য হালনাগদ করবো।&nbsp;</p>', '1671019008197390001_4051713664882621_1080239185636244229_n.jpg', 1, 0, '2022-01-02 13:38:49', '2023-09-08 22:02:13'),
(17, 'চিকনাগুল স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র।', '2021-01-02', '<p>১৬ সেপ্টেম্বর ২০২৩ইং &#39;চিকনাগুল স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র&#39;-এর আনুষ্ঠানিক উদ্বোধন করেন বাংলাদেশ প্রবাসী কল্যাণ ও বৈদেশিক কর্মসংস্থান মন্ত্রী ইমরান আহমেদ। উদ্বোধনী অনুষ্ঠান বিকেল ৪ ঘটিকায় অনুষ্টিত হয়। গ্রামের ছোট-বড় সবাইকে উক্ত উদ্বোধনী অনুষ্ঠানে উপস্থিত ছিলেন। সম্পূর্ণ&nbsp;তথ্য হালনাগাদের কাজ চলছে......</p>', '1694809335চিকনাগুল স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র.webp', 1, 0, '2022-01-03 01:22:15', '2023-09-16 00:22:15'),
(18, 'উমনপুর পাহাড় মসজিদ', '2023-08-18', '<p>উমনপুর পাহাড় মসজিদের বাহিরের নকশা। উমনপুর পাহাড় মসজিদ তিন তলা বিশিষ্ট&nbsp;নকশায় নির্মিত হবে&nbsp;এবং অতি শীঘ্রই মসজিদের নির্মাণ কাজ শুরু হবে।</p>', '1695968597Umonpur-pahar-mosquee.webp', 1, 0, '2023-08-18 10:09:59', '2023-09-29 15:11:26'),
(19, 'উমনপুর সমাজ কল্যাণ সংঘ', '2023-09-20', '<p>উমনপুর গ্রামের যুব সমাজের উদ্যেগে&nbsp; উমনপুর গ্রামের উন্নয়ন মূলক কাজের জন্যে উমনপুর সমাজ কল্যাণ সংঘটন তৈরী করা হয়। উমনপুর সমাজ কল্যাণ সংঘ&#39;র তথ্য হালনাগাদের কাজ চলমান...</p>', '1718911387umonpur-wellfare-association-2.webp', 1, 0, '2024-06-20 23:14:42', '2024-11-27 11:45:04');
