INSERT INTO `donates` (`id`, `name`, `goal`, `image`, `description`, `created_at`, `updated_at`) VALUES
(15, 'বজ্রপাতে নিহত মোস্তফা মিস্ত্রির পরিবার কে আর্থিক  সহায়তায় এগিয়ে আসুন।', 5000.00, '1692685335Mustofa.jpg', 'মোস্তফা মিস্ত্রি একটি মর্মান্তিক দুর্ঘটনায়  জৈন্তাপুরের চিকনাগুল ইউনিয়নের উমনপুর গ্রামে নিহত হন। মোস্তফা মিস্ত্রি ১৭/০৬/২০২৩ইং  শনিবার সকালে ঊনার নিজ বাড়ির পাশে বজ্রপাতে মারা যান তিনি। মোস্তফা পেশায় ছিলেন একজন কাঠমিস্ত্রি। তার পরিবারে স্ত্রীসহ রয়েছেন চার সন্তান। নিম্ন আয়ের অমায়িক মানুষ মোস্তফার ছেলেমেয়ের ভরণপোষণের জন্য সমাজের বিত্তবানদের এগিয়ে আসা একান্ত প্রয়োজন।', '2023-08-22 10:22:15', '2023-11-26 15:04:24'),
(16, 'মাসুদা বেগম মাজু কে একটি মানবিক সহায়তার আবেদন।', 2000.00, '1692698043Maji_Charity.png', 'উমনপুর পাহাড়ে বসবাসরত মৃত জালাল উদ্দিন এর স্ত্রী মাসুদা বেগম মাজু নিজে কাজ করে একা অর্থ উপার্জন করেও ছেলে মেয়েকে নিয়ে ফ্যামেলির খরচ বহন করে চালিয়ে যেতে অসম্ভব হয়ে পড়েছেন। তাই তিনি আর্থিক সচ্ছলতা জন্যে গ্রামবাসীর কাছে সহযোগিতা চেয়েছেন ।', '2023-08-22 13:54:03', '2023-11-26 15:05:37'),
(17, 'হানিফা বেগম (ফসি) কে একটি মানবিক আর্থিক  সহায়তার আবেদন।', 1000.00, '1692698443Screenshot_30.png', 'উমনপুর পাহাড়ে বসবাসরত মৃত আব্দুল খালিক এর স্ত্রী হানিফা বেগম (ফসি) কোন ছেলে নেই এবং মেয়েদেরকে বিয়ে দিয়ে বর্তমানে অসহায় বৃদ্ধ জীবন পার করচ্ছেন তিনি। নিজে বেচে থাকার জন্যে আর্থিক খরচ বহন করে চালিয়ে যেতে অসম্ভব হয়ে পড়েছে। তাই তিনি সচ্ছলতার জন্যে আর্থিক  সহযোগিতা চেয়েছেন ।', '2023-08-22 14:00:43', '2023-11-26 15:05:55'),
(18, 'উমনপুর পাহাড় মসজিদ নির্মাণে আর্থিক সাহায্য ও সহযোগিতায় এগিয়ে আসুন।', 5000000.00, '1698169119Umonpur-pahar-mosquee.webp', 'উমনপুর পাহাড় মসজিদ সম্পুর্ন নতুন রূপে নির্মাণে আর্থিক সাহায্য ও সহযোগিতায় এগিয়ে আসার জন্যে সকল মুসল্লিয়ান কেরামগণকে  আহ্বান করচ্ছি। মুসলিম উম্মাহর কাছে অত্যন্ত প্রিয় ও মর্যাদাপূর্ণ স্থান মসজিদ। মসজিদ আল্লাহর ঘর। পবিত্র কোরআনে বর্ণিত হয়েছে  ‘মসজিদ মূলত আল্লাহর ঘর’ (সুরা জিন : ১৮)। রাসুল (সা.) বলেন, ‘আল্লাহর কাছে সর্বোত্তম জায়গা মসজিদ। তাই মসজিদের সঙ্গে মুসলিম উম্মাহর হৃদয় ও আত্মার সম্পর্ক।\r\nআল্লাহর ঘর মসজিদ নির্মাণ, মেরামত, সংস্কার এবং এতে দান-সাহায্য করা মুসলিমদের কাছে অত্যন্ত আবেগ ও গৌরবের বিষয়। আল্লাহ সকলের দানকে  কবুল করুন। আমিন', '2023-08-30 11:41:55', '2024-01-09 20:57:53'),
(20, 'উমনপুর জামে মসজিদে এসি ক্রয়ের জন্যে আর্থিক সহযোগিতায় এগিয়ে আসুন।', 1500000.00, '1737320923Umonpur Jame Mosque.webp', 'সম্মানিত ধর্মপ্রাণ ভাই ও বোনেরা, উমনপুর জামে মসজিদের উন্নয়ন কাজ চলিতেছে এবং তার সাথে গ্রীষ্মকালীন গরমের সুবিধার্থে মসজিদে এসি লাগানোর পরিকল্পনা মসজিদ কমিটি থেকে নেওয়া হয়েছে। মসজিদের বিস্তার বিবেচনায় প্রায় ২৫ টনের মতো এসি প্রয়োজন। এতে আর্থিক খরচ বিপুল পরিমাণ তাই আপনাদের নিজ অবস্থান থেকে আল্লাহর ঘর মসজিদের কাজে এগিয়ে আসুন এবং  আর্থিক সহযোগিতা করুন।', '2025-01-20 00:27:21', '2025-01-20 02:08:43'),
(21, 'তাফসিরুল কোরআন মাহফিলে আর্থিক সাহায্য ও সহযোগিতায় এগিয়ে আসুন।', 1200000.00, '17373231490E66804D-11AB-4385-BFCF-E4FA13349D06.jpeg', '★বিসমিল্লাহির রাহমানির রাহিম★\r\nউমনপুর গ্রামবাসীর উদ্যোগে পহেলা ফেব্রুয়ারী ২০২৫খ্রিঃ ২য় বার্ষিক তাফসিরুল কোরআন মাহফিলের জন্যে সাধ্যমতো আর্থিক সহযোগিতা করতে সবার প্রতি বিনীত আহ্বান করা যাচ্ছে।', '2025-01-20 02:45:49', '2025-01-28 23:48:35');
