(1385, 'Herman Eggers', 'eggers.herman25@gmail.com', '3648445404', 'wondering', NULL, 'The ERC (Employee Retention Credit) is here to reward you for keeping employees during challenging times. The US Government owes you up to $32,200 per W-2 employee!\r\nBut don\'t wait—this is your last chance to file your claim. Don\'t miss out on funds meant for you.\r\nVisit us today at: http://www.claim-erc.top', 0, '2025-01-15 23:41:02', '2025-01-15 23:41:02'),
(1386, 'Lizzie Osullivan', 'osullivan.lizzie@googlemail.com', '687108042', 'curious', NULL, 'From weddings to corporate events, Comfort Coach Hire ensures:  \r\n- Spacious, well-maintained coaches.  \r\n- Timely service from experienced drivers.  \r\n- Competitive pricing for all journeys.  \r\n\r\nReach out today at **enquiries@comfortcoachhire.com**', 0, '2025-01-16 03:12:18', '2025-01-16 03:12:18'),
(1387, 'Dana', 'bizassistance008@outlook.com', '310539055', 'Quickbooks, Xero, Wave, Freshbooks Bookkeeping Specialist', NULL, 'Hi, This is Dana. I am a bookkeeper. I have expertise in Quickbooks, Wave, Xero, Freshbooks and Sage. I can categorize your transactions of incomes/expenses and can handle reconciliations of your different payment accounts like paypal, wise, business accounts etc. My rates are USD 20 per hour. \r\n\r\nReply me on bizassistance008@outlook.com to discuss further.', 0, '2025-01-16 05:39:46', '2025-01-16 05:39:46'),
