INSERT INTO `posts` (`id`, `date`, `user_id`, `cat_id`, `cat_sub_id`, `title`, `image`, `sub_title`, `description`, `created_at`, `updated_at`) VALUES
(1, '2020-02-14', 1, 1, NULL, 'অফিসিয়াল ওয়েবসাইটের অভিষেক অনুষ্টান।', '1672178856untitled-project-time-0-00-1122.webp', NULL, 'উমনপুর গ্রামের সকল ব্যাক্তি বর্গ মিলে ১৪/০২/২০২১ইং অফিসিয়াল ওয়েবসাইটের অভিষেক অনুষ্টান জাকজমক করে পালন করেন। উমনপুর গ্রামের সকল ব্যাক্তি বর্গ মিলে  অফিসিয়াল ওয়েবসাইটের অভিষেক অনুষ্টান জাকজমক করে পালন করেন।', '2022-11-16 13:53:50', '2022-12-27 16:07:36'),
(2, '2022-01-01', 1, 1, NULL, 'নতুন বছরে শিশুদের বই বিতরণ।', '1672178121rsz-img-20220101-wa0007.webp', NULL, 'নতুন বছরে উমনপুর সরকারী প্রাথমিক বিদ্যালয়ে  শিশুদের বই বিতরণ করা হয়। বই বিতরনে উপস্থিত ছিলেন উমনপুর সরকারী প্রাথমিক বিদ্যালয়ের সভাপতি জনাব মোঃ আব্দুল মোমেন, প্রধান শিক্ষ জনাব মোঃ নুরুল ইসলাম, উমনপুর গ্রামের মেম্বার জনাব ফারুক আহমেদ এবং বিদ্যালয়ের শিক্ষক মন্ডলীগ্ণ।', '2022-11-16 13:54:32', '2022-12-27 15:55:21'),
(4, '2022-11-18', 1, 1, NULL, 'জামে মসজিদের ওয়াশ ব্লক এর ব্যবহার শুরু।', '1672178086rsz-img-1857.webp', NULL, '<p>উমনপুর জামে মসজিদের ওয়াশ ব্লক এর ব্যবহার শুরু হয়েছে। এই অত্যাধুনিক ওয়াশব্লক দেখতে খুবী চমৎকার ঠিক&nbsp; তেমনি ব্যবহাররে সন্তুষ্ট ভাব পাওয়া যায়।</p>', '2022-11-16 13:56:35', '2023-09-08 22:38:28'),
(5, '2022-11-18', 1, 2, NULL, 'শনিবার আছর পরে জামে মসজিদে মিটিং।', '', NULL, 'গত শনিবার দুপুরে সরেজমিনে দেখা গেছে, নৌকায় গাদাগাদি করে যাত্রীরা পার হচ্ছেন। নৌকার ওপরে ছাউনি নেই। নেই নিরাপত্তামূলক ব্যবস্থা। ধারণক্ষমতার অতিরিক্ত যাত্রী বহন হচ্ছে। ঈদের কয়েক দিন আগে থেকে এ অবস্থা চলছে।', '2022-11-16 13:57:48', '2023-02-06 06:47:34'),
(6, '2022-11-17', 1, 2, NULL, 'সফটওয়ারের কাজ চলছে আপনারা দোয়া করবেন।', '', NULL, 'গত শনিবার দুপুরে সরেজমিনে দেখা গেছে, নৌকায় গাদাগাদি করে যাত্রীরা পার হচ্ছেন। নৌকার ওপরে ছাউনি নেই। নেই নিরাপত্তামূলক ব্যবস্থা। ধারণক্ষমতার অতিরিক্ত যাত্রী বহন হচ্ছে। ঈদের কয়েক দিন আগে থেকে এ অবস্থা চলছে।', '2022-11-16 13:58:26', '2023-02-06 06:48:41'),
(7, '2022-11-19', 1, 2, NULL, 'ওয়েবসাইটের ৩য় বর্ষপূর্তি উৎযাপন।', '', NULL, 'উমনপুর গ্রামের অফিসিয়াল ওয়েবসাইটের ৩য় বর্ষপূর্তি উৎযাপন করা হবে আগামী ১৪/০২২০২৩ইং। নৌকার ওপরে ছাউনি নেই। নেই নিরাপত্তামূলক ব্যবস্থা। ধারণক্ষমতার অতিরিক্ত যাত্রী বহন হচ্ছে। ঈদের কয়েক দিন আগে থেকে এ অবস্থা চলছে।', '2022-11-16 14:00:20', '2023-02-06 06:45:40'),
(8, '2022-11-18', 1, 2, NULL, 'আগামী শুক্রবার মিটিং', '', NULL, 'আগামী শুক্রবার বাদ জুম্মা উমনপুর জামে মসজীদে মিটিং , নৌকায় গাদাগাদি করে যাত্রীরা পার হচ্ছেন। নৌকার ওপরে ছাউনি নেই। নেই নিরাপত্তামূলক ব্যবস্থা। ধারণক্ষমতার অতিরিক্ত যাত্রী বহন হচ্ছে। ঈদের কয়েক দিন আগে থেকে এ অবস্থা চলছে।', '2022-11-16 14:00:42', '2022-12-09 14:48:05'),
(9, '2022-11-19', 1, 3, NULL, 'উমনপুর গ্রামের ওয়েবসাইটের অভিষেক অনুষ্ঠান।', '', NULL, '<p>উমনপুর গ্রামের অফিসিয়াল ওয়েবসাইটের অভিষেক অনুষ্ঠানে উমনপুর গ্রামের ছোট - বড় সবাইকে উপস্থিত থাকার আহ্বান করা হইলো।</p>', '2022-11-16 14:03:53', '2023-10-23 22:48:58'),
