(11, '2022-12-03', 1, 3, NULL, 'তৃতীয় বারি পলা বাওয়া উৎসব।', '', NULL, '<p>উমনপুর গ্রামের দুল্ভ বিলে তৃতীয় বারি পলা বাওয়া উৎসব পালিত হবে। নৌকার ওপরে ছাউনি নেই। নেই নিরাপত্তামূলক ব্যবস্থা। ধারণক্ষমতার অতিরিক্ত যাত্রী বহন হচ্ছে। ঈদের কয়েক দিন আগে থেকে এ অবস্থা চলছে।</p>', '2022-11-16 14:04:20', '2023-10-23 22:55:00'),
