(47, '2022-11-11', 1, 2, NULL, 'আগামী সপ্তাহে উপদেষ্টা মণ্ডলীগণের মিটিং', '1669056772Professor-Dr.-Yousuf-Mahbubul-Islam.png', NULL, 'আসছে আগামী ১৭/১২/২০২২ইং রবিবার  উপদেষ্টা মণ্ডলীগণের মিটিং এর আয়োজন করা হচ্ছে আমা । নৌকার ওপরে ছাউনি নেই। নেই নিরাপত্তামূলক ব্যবস্থা। ধারণক্ষমতার অতিরিক্ত যাত্রী বহন হচ্ছে। ঈদের কয়েক দিন আগে থেকে এ অবস্থা চলছে।', '2022-11-21 12:52:52', '2022-12-09 14:40:38'),
(48, '2022-12-09', 1, 2, NULL, 'শনিবার পর থেকে পলো বাওয়া বন্ধ ঘোষণা করা হল।', '', NULL, '<p>আগামী শনিবার ১০/১২/২০২২ইং চলিত বছরে সর্বশেষ পলো বাওয়া ।</p>\r\n\r\n<p>না দুপুরে সরেজমিনে দেখা গেছে, নৌকায় গাদাগাদি করে যাত্রীরা পার হচ্ছেন। নৌকার ওপরে ছাউনি নেই। নেই নিরাপত্তামূলক ব্যবস্থা।</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>ধারণক্ষমতার অতিরিক্ত যাত্রী বহন হচ্ছে। ঈদের কয়েক দিন আগে থেকে এ অবস্থা চলছে।</p>', '2022-11-21 12:53:43', '2023-02-26 00:06:06'),
(52, '2021-12-02', 1, 1, NULL, 'চলিত বছরে আর পলো বাওয়া হচ্ছে না।', '1672178070rsz-img-3925.webp', NULL, '<p>আগামী শনিবার ১০/১২/২০২২ইং চলিত বছরে সর্বশেষ পলো বাওয়া।&nbsp;</p>', '2022-11-23 11:39:57', '2023-08-21 00:04:37'),
(53, '2020-12-09', 1, 8, NULL, 'স্বাস্থ্য কপ্লেক্স এর জন্য জমি পরিদর্শন', '1672421660chcu-3.webp', NULL, 'স্বাস্থ্য কপ্লেক্স এর জন্য জমি পরিদর্শন  , চিকনাগুল স্বাস্থ্য কপ্লেক্স এর নির্মাণ কাজ শুরু , চিকনাগুল স্বাস্থ্য কপ্লেক্স এর নির্মাণ কাজ শুরু । চিকনাগুল স্বাস্থ্য কপ্লেক্স এর নির্মাণ কাজ শুরু  চিকনাগুল স্বাস্থ্য কপ্লেক্স এর নির্মাণ কাজ শুরু ।', '2022-12-07 23:33:54', '2022-12-30 11:34:20'),
(54, '2023-02-14', 1, 3, NULL, 'ওয়েবসাইটের  তৃতীয় বর্ষপুর্তি উৎযাপন।', '', NULL, '<p>উমনপুর গ্রামের ছোট বড় সবাই মিলে ওয়েবসাইটের তৃতীয় বর্ষপুর্তি উৎযাপন করবেন আগামী ১৪ই ফেব্রুয়ারি ২০২৩ইং।</p>', '2022-12-09 15:42:05', '2023-10-23 22:55:21'),
(55, '2022-12-08', 1, 4, NULL, 'দুলভ বিলে পলো বাওয়া উৎসব।', '1672252167rsz-img-e3957.webp', NULL, '<p>প্রতি বছরে উমনপুর গ্রামের আবাল বৃদ্ধ বনেতা উমনপুর দুল্ভ বিলে পলো বাওয়া উৎসবে&nbsp; অংশগ্রহন করেন। এটি উমনপুর গ্রামে ঐতিহ্য এই দুল্ভ বিল। এই বিলে গ্রামের মানুষের অনেক স্মৃতি বিজড়িত।&nbsp; &nbsp;</p>', '2022-12-11 19:19:55', '2023-09-08 22:27:22'),
(56, '2022-12-13', 1, 4, NULL, 'উমনপুর পাঞ্জেগানা মসজিদ।', '1672252894rsz-120210423-173640.webp', NULL, '<p>উমনপুর পাঞ্জেগানা মসজিদ উমনপুর পাহাড় এলাকায় অবস্থিত। এটি হাইওয়ে রোড থেকে ৪১০ মিটার দূরত্বে অবস্থিত।</p>', '2022-12-11 19:20:24', '2023-09-08 22:26:43'),
(57, '2022-12-17', 1, 4, NULL, 'উমনপুর পাহাড় ব্রিজ দুই।', '1672252932rsz-20210504-175150.webp', NULL, '<p>উমনপুর গ্রামের পাড় রোডে এই ব্রিজটি অবস্থিত। উমনপুর গ্রামের মধ্যদিয়ে সিলেট টু জাফ্লং রোড এর উমনপুর টার্নিং&nbsp; হতে ৪১৪ মিটার দূরত্বে অবস্থিত। এই ব্রিজ সংলগ্ন উমনপুর পাঞ্জেগান মসজিদ অবস্থিত।</p>', '2022-12-11 19:25:51', '2023-09-08 22:23:39'),
(58, '2022-12-17', 1, 5, NULL, 'উমনপুর সরকারী প্রাথমিক বিদ্যালয়।', '1672256480rsz-img-0212.webp', NULL, 'উমনপুর সরকারী প্রাথমিক বিদ্যালয়ে ছাত্র-ছাত্রীদের ক্লাস চলাকালীন সময়ে প্রধান শিক্ষক জনাব মোঃ নুরুল ইসলাম পরিদর্শনকালীন সময় ছাত্র ছাত্রীদের লেখা-পড়া সঠিক হচ্ছে কি না দেখবাল করছেন।', '2022-12-11 19:37:27', '2023-02-01 13:56:20'),
(59, '2022-12-16', 1, 5, NULL, 'ইংরেজী নভবর্ষে ছাত্র-ছাত্রীদের বই বিতরণ', '1672256512rsz-2img-20220101-wa0009.webp', NULL, 'উমনপুর সরকারী প্রাথমিক বিদ্যালয়ে ছাত্র-ছাত্রীদের ক্লাস চলাকালীন সময়ে প্রধান শিক্ষক জনাব মোঃ নুরুল ইসলাম পরিদর্শনকালীন সময় ছাত্র ছাত্রীদের লেখা-পড়া সঠিক হচ্ছে কি না দেখবাল করছেন।', '2022-12-11 19:38:04', '2023-02-01 13:53:04'),
(60, '2022-12-09', 1, 5, NULL, 'করুণা ভাইরাস নিয়ে শতর্ক থাকার প্রশিক্ষণ', '1672256586img-20211113-wa0006.webp', NULL, 'উমনপুর সরকারী প্রাথমিক বিদ্যালয়ে ছাত্র-ছাত্রীদের ক্লাস চলাকালীন সময়ে প্রধান শিক্ষক জনাব মোঃ নুরুল ইসলাম পরিদর্শনকালীন সময় ছাত্র ছাত্রীদের লেখা-পড়া সঠিক হচ্ছে কি না দেখবাল করছেন।', '2022-12-11 19:38:58', '2023-02-01 13:51:20'),
(61, '2022-12-09', 1, 5, NULL, 'স্কুলের মনুগ্রাম  ছাত্র-ছাত্রীদের পূষাকে।', '1672256638rsz-img-3073.webp', NULL, 'উমনপুর সরকারী প্রাথমিক বিদ্যালয়ে ছাত্র-ছাত্রীদের ক্লাস চলাকালীন সময়ে প্রধান শিক্ষক জনাব মোঃ নুরুল ইসলাম পরিদর্শনকালীন সময় ছাত্র ছাত্রীদের লেখা-পড়া সঠিক হচ্ছে কি না দেখবাল করছেন।', '2022-12-11 19:39:30', '2023-02-01 13:55:12'),
(62, '2022-12-02', 1, 7, NULL, 'আমাদের খেলাধুলা ৬', '16724258621672139475noyabari-akadosh.webp', NULL, 'একাত্তরে সিলেটের মুরারিচাঁদ (এমসি) কলেজের বিজ্ঞান বিভাগের দ্বাদশ শ্রেণির ছাত্র ছিলেন শ্রীকান্ত দাস। ৭ মার্চ বঙ্গবন্ধু শেখ মুজিবুর রহমানের ভাষণের পর পরিস্থিতি বদলে যায়। শহর হয়ে পড়ে জনশূন্য। এ অবস্থায় শিক্ষার্থীরাও ছাত্রাবাস ছাড়েন। অন্য অনেকের মতো শ্রীকান্তও বাড়ি ফেরেন।\r\n\r\nআরও পড়ুন\r\n‘আমার কিছু হবে না’ বলে বেরিয়ে গিয়েছিলেন বাবা\r\n‘আমার কিছু হবে না’ বলে বেরিয়ে গিয়েছিলেন বাবা\r\nহবিগঞ্জের আজমিরীগঞ্জ উপজেলার বদলপুর ইউনিয়নের পাহাড়পুর গ্রামে শ্রীকান্তের বাড়ি। ১৯৫২ সালে হাওরের এই প্রত্যন্ত গ্রামের এক দরিদ্র পরিবারে তাঁর জন্ম। বাবা নীলকান্ত দাস ও মা চন্দ্রময়ী দাসের চার সন্তানের মধ্যে তিনি ছিলেন দ্বিতীয়। গ্রামের বিদ্যালয়ে প্রাথমিক পর্যন্ত পড়েন। এরপর ১৯৬৯ সালে বিজ্ঞান বিভাগের শিক্ষার্থী হিসেবে বিরাট এএবিসি হাইস্কুল থেকে প্রথম শ্রেণিতে ম্যাট্রিকুলেশন পাস করেন। এরপরই ভর্তি হন এমসি কলেজে।\r\n\r\nবাড়ি ফিরে দেশের সামগ্রিক পরিস্থিতির দিকে নজর রাখেন শ্রীকান্ত। মুক্তিযুদ্ধ শুরু হলে যুদ্ধে যাওয়ার প্রস্তুতি নেন। গ্রামের আরও কয়েকজনকে মুক্তিযুদ্ধে যাওয়ার জন্য উৎসাহ দেন। পরে শ্রীকান্ত ১৭ মে গোপাল চক্রবর্তী, হরিপ্রসন্ন চক্রবর্তী ও সুশান্ত দাসকে নিয়ে ভারতের মেঘালয়ে চলে যান। ২৮ দিনের প্রশিক্ষণ শেষে দেশে ফিরে তাঁরা ৫ নম্বর সেক্টরে যোগ দেন। প্রশিক্ষণকালে শ্রীকান্তের ব্যাচ নম্বর ছিল ৬।\r\n\r\nবেশ কিছু গুরুত্বপূর্ণ অপারেশনে অংশ নেন শ্রীকান্ত দাস। ১৯৭১ সালের ২৭ নভেম্বর সুনামগঞ্জের বৈশেরপাড়া ষোলগড় ডলুরা এলাকায় সম্মুখযুদ্ধে শহীদ হন তিনি। বেয়নেট দিয়ে খুঁচিয়ে তাঁর হৃৎপিণ্ড ও চোখ তুলে নেয় পাকিস্তান সেনাবাহিনী। রাস্তায় পড়ে ছিল তাঁর লাশ। পরে ডলুরা গণকবরে তাঁকে সমাহিত করা হয়। এই গণকবরের ৪৪ নম্বর স্মৃতিস্মারকটি হচ্ছে শ্রীকান্ত দাসের।\r\n\r\nমুক্তিযুদ্ধ শেষে ধীরে ধীরে পরিস্থিতি স্বাভাবিক হয়। এমসি কলেজ ছাত্রাবাসেও ফিরতে শুরু করেন শিক্ষার্থীরা। ১৯৭২ সালের শেষ দিকে শ্রীকান্তের স্মৃতিকে স্মরণীয় করে রাখতে শিক্ষার্থীরা ‘শহীদ শ্রীকান্ত ছাত্রাবাস’ সাইনবোর্ড ছাত্রাবাসের ব্লকে সাঁটিয়ে দেন।\r\n\r\nসে সময় ছাত্রাবাসের বাসিন্দা ছিলেন রসায়ন বিভাগের স্নাতকের শিক্ষার্থী তমাল কুমার বিশ্বাস। এখন তিনি হবিগঞ্জে আইনপেশায় যুক্ত। সত্তরোর্ধ্ব তমাল জানান, শহীদ শ্রীকান্তের স্মৃতি রক্ষায় কলেজ প্রশাসনকে অনুরোধ করলে তাঁরা গুরুত্ব দেননি। ছাত্ররা সাইনবোর্ড লাগিয়ে দেওয়ার পর অবশ্য কলেজ কর্তৃপক্ষও কাগজপত্রে শহীদ শ্রীকান্ত ছাত্রাবাস নামটি বহাল রাখে।\r\n\r\nএকটি সাইনবোর্ড ছাড়া ছাত্রাবাসটিতে আর কিছুই পাওয়া যায়নি। নেই কোনো ছবি বা স্মৃতিচিহ্ন। এ নিয়ে আবাসিক শিক্ষার্থীদের আক্ষেপও আছে। এ বিষয়ে শহীদ শ্রীকান্ত ছাত্রাবাসের বর্তমান হোস্টেল সুপার জীবনকৃষ্ণ আচার্য জানান, নামকরণটুকু ছাড়া শহীদ শ্রীকান্তের কোনো স্মৃতিচিহ্ন ছাত্রাবাসে নেই।\r\n\r\nশহীদ শ্রীকান্তের গ্রামের বাড়িতে ১১ ডিসেম্বর রাতে খোঁজ নেওয়া হয়। শ্রীকান্তের বড় ভাই রতিকান্ত দাসের ছেলে সুজিত কুমার দাস (৫১) জানান, তাঁর বাবারা ছিলেন তিন ভাই। শ্রীকান্ত ছিলেন মেজ। শ্রীকান্তের বড় ভাই রতিকান্ত ২০০৯ সালে মারা যান। তবে শ্রীকান্তের ছোট ভাই উমাকান্ত দাস (৭০) জীবিত। এ ছাড়া ময়তারা দাস (৬০) নামে শ্রীকান্তের এক ছোট বোন আছেন।\r\n\r\nসুজিত বলেন, তিনি ও তাঁর চাচা উমাকান্ত কৃষিজীবী। একেবারেই অসচ্ছল পরিবারের মানুষ তাঁরা। তবে এ নিয়ে তাঁদের কোনো আক্ষেপ নেই। আক্ষেপ কেবল এই, শহীদ পরিবার হিসেবে তাঁরা কোনো ভাতা পাওয়া তো দূরের কথা, মর্যাদাটুকুও পাচ্ছেন না। শহীদ শ্রীকান্তের স্মৃতি রক্ষায়ও তেমন কোনো উদ্যোগ নেই।', '2022-12-11 20:07:20', '2022-12-30 12:44:22'),
(63, '2022-11-30', 1, 8, NULL, 'চিকনাগুল স্বাস্থ্য কপ্লেক্স এর নির্মাণ কাজ শুরু', '1672421869chcu-6.webp', NULL, 'চিকনাগুল স্বাস্থ্য কপ্লেক্স এর নির্মাণ কাজ শুরু...।একাত্তরে সিলেটের মুরারিচাঁদ (এমসি) কলেজের বিজ্ঞান বিভাগের দ্বাদশ শ্রেণির ছাত্র ছিলেন শ্রীকান্ত দাস। ৭ মার্চ বঙ্গবন্ধু শেখ মুজিবুর রহমানের ভাষণের পর পরিস্থিতি বদলে যায়। শহর হয়ে পড়ে জনশূন্য। এ অবস্থায় শিক্ষার্থীরাও ছাত্রাবাস ছাড়েন। অন্য অনেকের মতো শ্রীকান্তও বাড়ি ফেরেন।\r\n\r\nআরও পড়ুন\r\n‘আমার কিছু হবে না’ বলে বেরিয়ে গিয়েছিলেন বাবা\r\n‘আমার কিছু হবে না’ বলে বেরিয়ে গিয়েছিলেন বাবা\r\nহবিগঞ্জের আজমিরীগঞ্জ উপজেলার বদলপুর ইউনিয়নের পাহাড়পুর গ্রামে শ্রীকান্তের বাড়ি। ১৯৫২ সালে হাওরের এই প্রত্যন্ত গ্রামের এক দরিদ্র পরিবারে তাঁর জন্ম। বাবা নীলকান্ত দাস ও মা চন্দ্রময়ী দাসের চার সন্তানের মধ্যে তিনি ছিলেন দ্বিতীয়। গ্রামের বিদ্যালয়ে প্রাথমিক পর্যন্ত পড়েন। এরপর ১৯৬৯ সালে বিজ্ঞান বিভাগের শিক্ষার্থী হিসেবে বিরাট এএবিসি হাইস্কুল থেকে প্রথম শ্রেণিতে ম্যাট্রিকুলেশন পাস করেন। এরপরই ভর্তি হন এমসি কলেজে।\r\n\r\nবাড়ি ফিরে দেশের সামগ্রিক পরিস্থিতির দিকে নজর রাখেন শ্রীকান্ত। মুক্তিযুদ্ধ শুরু হলে যুদ্ধে যাওয়ার প্রস্তুতি নেন। গ্রামের আরও কয়েকজনকে মুক্তিযুদ্ধে যাওয়ার জন্য উৎসাহ দেন। পরে শ্রীকান্ত ১৭ মে গোপাল চক্রবর্তী, হরিপ্রসন্ন চক্রবর্তী ও সুশান্ত দাসকে নিয়ে ভারতের মেঘালয়ে চলে যান। ২৮ দিনের প্রশিক্ষণ শেষে দেশে ফিরে তাঁরা ৫ নম্বর সেক্টরে যোগ দেন। প্রশিক্ষণকালে শ্রীকান্তের ব্যাচ নম্বর ছিল ৬।\r\n\r\nবেশ কিছু গুরুত্বপূর্ণ অপারেশনে অংশ নেন শ্রীকান্ত দাস। ১৯৭১ সালের ২৭ নভেম্বর সুনামগঞ্জের বৈশেরপাড়া ষোলগড় ডলুরা এলাকায় সম্মুখযুদ্ধে শহীদ হন তিনি। বেয়নেট দিয়ে খুঁচিয়ে তাঁর হৃৎপিণ্ড ও চোখ তুলে নেয় পাকিস্তান সেনাবাহিনী। রাস্তায় পড়ে ছিল তাঁর লাশ। পরে ডলুরা গণকবরে তাঁকে সমাহিত করা হয়। এই গণকবরের ৪৪ নম্বর স্মৃতিস্মারকটি হচ্ছে শ্রীকান্ত দাসের।\r\n\r\nমুক্তিযুদ্ধ শেষে ধীরে ধীরে পরিস্থিতি স্বাভাবিক হয়। এমসি কলেজ ছাত্রাবাসেও ফিরতে শুরু করেন শিক্ষার্থীরা। ১৯৭২ সালের শেষ দিকে শ্রীকান্তের স্মৃতিকে স্মরণীয় করে রাখতে শিক্ষার্থীরা ‘শহীদ শ্রীকান্ত ছাত্রাবাস’ সাইনবোর্ড ছাত্রাবাসের ব্লকে সাঁটিয়ে দেন।\r\n\r\nসে সময় ছাত্রাবাসের বাসিন্দা ছিলেন রসায়ন বিভাগের স্নাতকের শিক্ষার্থী তমাল কুমার বিশ্বাস। এখন তিনি হবিগঞ্জে আইনপেশায় যুক্ত। সত্তরোর্ধ্ব তমাল জানান, শহীদ শ্রীকান্তের স্মৃতি রক্ষায় কলেজ প্রশাসনকে অনুরোধ করলে তাঁরা গুরুত্ব দেননি। ছাত্ররা সাইনবোর্ড লাগিয়ে দেওয়ার পর অবশ্য কলেজ কর্তৃপক্ষও কাগজপত্রে শহীদ শ্রীকান্ত ছাত্রাবাস নামটি বহাল রাখে।\r\n\r\nএকটি সাইনবোর্ড ছাড়া ছাত্রাবাসটিতে আর কিছুই পাওয়া যায়নি। নেই কোনো ছবি বা স্মৃতিচিহ্ন। এ নিয়ে আবাসিক শিক্ষার্থীদের আক্ষেপও আছে। এ বিষয়ে শহীদ শ্রীকান্ত ছাত্রাবাসের বর্তমান হোস্টেল সুপার জীবনকৃষ্ণ আচার্য জানান, নামকরণটুকু ছাড়া শহীদ শ্রীকান্তের কোনো স্মৃতিচিহ্ন ছাত্রাবাসে নেই।\r\n\r\nশহীদ শ্রীকান্তের গ্রামের বাড়িতে ১১ ডিসেম্বর রাতে খোঁজ নেওয়া হয়। শ্রীকান্তের বড় ভাই রতিকান্ত দাসের ছেলে সুজিত কুমার দাস (৫১) জানান, তাঁর বাবারা ছিলেন তিন ভাই। শ্রীকান্ত ছিলেন মেজ। শ্রীকান্তের বড় ভাই রতিকান্ত ২০০৯ সালে মারা যান। তবে শ্রীকান্তের ছোট ভাই উমাকান্ত দাস (৭০) জীবিত। এ ছাড়া ময়তারা দাস (৬০) নামে শ্রীকান্তের এক ছোট বোন আছেন।\r\n\r\nসুজিত বলেন, তিনি ও তাঁর চাচা উমাকান্ত কৃষিজীবী। একেবারেই অসচ্ছল পরিবারের মানুষ তাঁরা। তবে এ নিয়ে তাঁদের কোনো আক্ষেপ নেই। আক্ষেপ কেবল এই, শহীদ পরিবার হিসেবে তাঁরা কোনো ভাতা পাওয়া তো দূরের কথা, মর্যাদাটুকুও পাচ্ছেন না। শহীদ শ্রীকান্তের স্মৃতি রক্ষায়ও তেমন কোনো উদ্যোগ নেই।', '2022-12-11 21:49:01', '2022-12-30 11:37:49'),
(66, '2022-12-10', 1, 8, NULL, 'স্বাস্থ্য কমপ্লেক্সের বেইজমেন্ট এর কাজ চলছে।', '1672421937chcu-8.webp', NULL, 'স্বাস্থ্য কমপ্লেক্সের বেইজমেন্ট এর কাজ চলছে। ।স্বাস্থ্য কমপ্লেক্সের দ্বিতীয় তলার ডালাই কাজ চলচ্ছে।স্বাস্থ্য কমপ্লেক্সের দ্বিতীয় তলার ডালাই কাজ চলচ্ছে।স্বাস্থ্য কমপ্লেক্সের দ্বিতীয় তলার ডালাই কাজ চলচ্ছে।', '2022-12-13 16:34:50', '2022-12-30 11:38:57'),
(67, '2022-12-11', 1, 8, NULL, 'দ্বী তলা বভনের ডালাই কাজ চলমান।', '1672422809rsz-1img-0225.webp', NULL, 'স্বাস্থ্য কমপ্লেক্স এর দ্বী তলা বভনের ডালাই কাজ চলচ্ছে। স্বাস্থ্য কমপ্লেক্সের দ্বিতীয় তলার ডালাই কাজ চলচ্ছে।স্বাস্থ্য কমপ্লেক্সের দ্বিতীয় তলার ডালাই কাজ চলচ্ছে।স্বাস্থ্য কমপ্লেক্সের দ্বিতীয় তলার ডালাই কাজ চলচ্ছে।', '2022-12-13 16:40:32', '2022-12-30 11:55:42'),
(68, '2022-12-13', 1, 8, NULL, 'স্বাস্থ্য কমপ্লেক্সের কাজ শেষের দিকে', '1672422835rsz-1img-e2998.webp', NULL, 'স্বাস্থ্য কমপ্লেক্সের কাজ শেষের দিকে । স্বাস্থ্য কমপ্লেক্সের আউটডোরের রঙ্গের কাজ শেষ।স্বাস্থ্য কমপ্লেক্সের আউটডোরের রঙ্গের কাজ শেষ।স্বাস্থ্য কমপ্লেক্সের আউটডোরের রঙ্গের কাজ শেষ।স্বাস্থ্য কমপ্লেক্সের আউটডোরের রঙ্গের কাজ শেষ।', '2022-12-13 16:43:21', '2022-12-30 11:53:55'),
(69, '2022-12-14', 1, 4, NULL, '৮ নং সিলেট হরিপুর গ্যাস ফিল্ড কূপ।', '1672252947rsz-img-3019.webp', NULL, '<p>উমনপুর গ্রামে দুইটি গ্যাস কূপ রয়েছে তার মধ্যে প্রধান কার্যালয়ের ছয় ভাগের এক ভাগ উমনপুর গ্রামের সীমার মধ্যে পড়েছে (&nbsp;প্রধান কার্যালয়ের উত্তর পাশ)। অপরটি ৮নং গ্যাস কূপ উমনপুর গ্রামের মধ্যে পড়েছে। ৮নং গ্যাস কূপকে গ্রামবাসী সিমিটার বলে ডাকেন।</p>', '2022-12-28 12:39:54', '2023-09-08 22:16:01'),
(70, '2022-12-06', 1, 4, NULL, 'উমনপুর হাইওয়ে ফিলিং ষ্টেশন।', '1672253383uhfs.webp', NULL, '<p>উমনপুর গ্রামেও চমৎকার হাইওয়ে ফিলিং ষ্টেশন রয়েছে যেইটি কিনা জৈন্তাপুর উপজেলার মধ্যে অত্যন্ত চমৎকার দেখতে এবং সর্বোচ্চ সেবা দিয়ে থাকেন।</p>', '2022-12-28 12:44:02', '2023-09-08 22:07:33'),
(71, '2022-12-06', 1, 4, NULL, 'পলো বাওয়া উৎসবে উমনপুর।', '1672253435rsz-1img-e3920.webp', NULL, '<p>প্রতি বছরে উমনপুর গ্রামের আবাল বৃদ্ধ বনেতা উমনপুর দুল্ভ বিলে পলো বাওয়া উৎসবে&nbsp; অংশগ্রহন করেন। এটি উমনপুর গ্রামে ঐতিহ্য এই দুল্ভ বিল। এই বিলে গ্রামের মানুষের অনেক স্মৃতি বিজড়িত।&nbsp; &nbsp;</p>', '2022-12-28 12:48:01', '2023-09-03 17:04:21'),
(72, '2022-12-09', 1, 4, NULL, 'সুইচ গেইট খালের পাড় ব্রিজ।', '1672253458rsz-img-e4096.webp', NULL, '<p>উমনপুর গ্রামের একটি মাত্র&nbsp; সুইচ গেইট খালের পাড়। এই ব্রিজের অবস্থান উমনপুর গ্রামের ঠিক পূর্বদিকে খাপনা নদীর দ্বারে&nbsp; অবস্থিত। সুইচ গেইটের এই খালটি উমনপুর পাহাড় পশ্চিম হতে গ্রামের মধ্যদিয়ে প্রবাহিত হয়ে গ্রামের পূর্বে কাপনা নদীতে মিলিত হয়েছে।&nbsp;</p>', '2022-12-28 12:50:58', '2023-09-03 16:57:21'),
(73, '2022-12-03', 1, 4, NULL, 'উমনপুর হাইওয়ে ফিলিং ষ্টেশন।', '1672253538rsz-20141120-220633.webp', NULL, '<p>উমনপুর গ্রামেও চমৎকার হাইওয়ে ফিলিং ষ্টেশন রয়েছে যেইটি কিনা জৈন্তাপুর উপজেলার মধ্যে অত্যন্ত চমৎকার দেখতে এবং সর্বোচ্চ সেবা দিয়ে থাকেন।</p>', '2022-12-28 12:52:18', '2023-09-08 22:05:36'),
(74, '2022-12-01', 1, 4, NULL, 'রাতে মুদীর দোকানের চমৎকার দৃশ্য।', '1672253574rsz-1img-0099.webp', NULL, '<p>রাতে মুদীর দোকানের দৃশ্য খুবী&nbsp;চমৎকার হয়। গ্রামের অনেক গুলা মুদী দোকান রয়েছে। বাড়ীর কাছাকাছি&nbsp;দোকান থাকায় গ্রামের মানুষ অল্প সময়ে বাজার করে ঘরে ফিরতে পারে।&nbsp;</p>', '2022-12-28 12:52:54', '2023-09-08 22:03:59'),
(75, '2022-12-01', 1, 4, NULL, 'অত্যাধুনিক ওয়াশ ব্লক, জামে মসজিদ।', '1672253960rsz-1img-1857.webp', NULL, '<p>উমনপুর গ্রামের অত্যাধুনিক ওয়াশ ব্লক। এই দুতলা স্থাপনার প্রথম তলায় অজুখান, প্রশ্রাব খানা এবং টয়লেট রয়েছে । দ্বিতীয় তলায় ইমাম ক্ষক এবং মক্তব রয়েছে।</p>', '2022-12-28 12:59:20', '2023-09-03 16:42:44'),
(76, '2022-12-14', 1, 4, NULL, 'ওয়েবসাইটের  তৃতীয় বর্ষপুর্তি উৎযাপন', '1672255830rsz-1rsz-1img-9807.webp', NULL, 'ওয়েবসাইটের  তৃতীয় বর্ষপুর্তি উৎযাপনওয়েবসাইটের  তৃতীয় বর্ষপুর্তি উৎযাপনওয়েবসাইটের  তৃতীয় বর্ষপুর্তি উৎযাপনওয়েবসাইটের  তৃতীয় বর্ষপুর্তি উৎযাপনওয়েবসাইটের  তৃতীয় বর্ষপুর্তি উৎযাপনওয়েবসাইটের  তৃতীয় বর্ষপুর্তি উৎযাপনওয়েবসাইটের  তৃতীয় বর্ষপুর্তি উৎযাপন', '2022-12-28 13:28:12', '2022-12-28 22:49:26'),
(77, '2022-12-02', 1, 5, NULL, 'অথ্যাধুনিক স্কুল উঃ সঃ প্রাঃ বিঃ', '1672256722rsz-1img-2982.webp', NULL, 'উমনপুর সরকারী প্রাথমিক বিদ্যালয়ে ছাত্র-ছাত্রীদের ক্লাস চলাকালীন সময়ে প্রধান শিক্ষক জনাব মোঃ নুরুল ইসলাম পরিদর্শনকালীন সময় ছাত্র ছাত্রীদের লেখা-পড়া সঠিক হচ্ছে কি না দেখবাল করছেন।', '2022-12-28 13:45:22', '2023-02-01 13:48:12'),
(78, '2022-12-01', 1, 5, NULL, 'করুনা প্রতিরুদে ছাত্রদের প্রশিক্ষণ', '1672256791img-20211113-wa0003.webp', NULL, 'উমনপুর সরকারী প্রাথমিক বিদ্যালয়ে ছাত্র-ছাত্রীদের ক্লাস চলাকালীন সময়ে প্রধান শিক্ষক জনাব মোঃ নুরুল ইসলাম পরিদর্শনকালীন সময় ছাত্র ছাত্রীদের লেখা-পড়া সঠিক হচ্ছে কি না দেখবাল করছেন।', '2022-12-28 13:46:31', '2023-02-01 13:47:06'),
(79, '2022-12-07', 1, 5, NULL, 'পরিদর্শন কালীন সময়  প্রধান শিক্ষক', '1672256814rsz-img-e4004.webp', NULL, 'উমনপুর সরকারী প্রাথমিক বিদ্যালয়ে ছাত্র-ছাত্রীদের ক্লাস চলাকালীন সময়ে প্রধান শিক্ষক জনাব মোঃ নুরুল ইসলাম পরিদর্শনকালীন সময় ছাত্র ছাত্রীদের লেখা-পড়া সঠিক হচ্ছে কি না দেখবাল করছেন।', '2022-12-28 13:46:54', '2023-02-01 13:44:24'),
(80, '2022-12-01', 1, 5, NULL, 'আর্ট এন্ড ক্র্যাফট রুম', '1672256834rsz-1img-4009.webp', NULL, 'উমনপুর সরকারী প্রাথমিক বিদ্যালয়ে ছাত্র-ছাত্রীদের ক্লাস চলাকালীন সময়ে প্রধান শিক্ষক জনাব মোঃ নুরুল ইসলাম পরিদর্শনকালীন সময় ছাত্র ছাত্রীদের লেখা-পড়া সঠিক হচ্ছে কি না দেখবাল করছেন।', '2022-12-28 13:47:14', '2023-02-01 13:45:20'),
(81, '2022-12-01', 1, 5, NULL, 'চিত্রাঙ্কন কক্ষ', '1672257242rsz-img-4011.webp', NULL, 'উমনপুর সরকারী প্রাথমিক বিদ্যালয়ে ছাত্র-ছাত্রীদের ক্লাস চলাকালীন সময়ে প্রধান শিক্ষক জনাব মোঃ নুরুল ইসলাম পরিদর্শনকালীন সময় ছাত্র ছাত্রীদের লেখা-পড়া সঠিক হচ্ছে কি না দেখবাল করছেন।', '2022-12-28 13:54:02', '2023-02-01 13:58:49'),
(82, '2022-12-24', 1, 8, NULL, 'স্বাস্থ্য কমপ্লেক্সের আউটডোরের রঙ্গের কাজ শেষ।', '1672422854rsz-img-e4018.webp', NULL, 'স্বাস্থ্য কমপ্লেক্সের আউটডোরের রঙ্গের কাজ শেষ। স্বাস্থ্য কমপ্লেক্সের আউটডোরের রঙ্গের কাজ শেষ।স্বাস্থ্য কমপ্লেক্সের আউটডোরের রঙ্গের কাজ শেষ।স্বাস্থ্য কমপ্লেক্সের আউটডোরের রঙ্গের কাজ শেষ।', '2022-12-30 11:43:55', '2022-12-30 11:54:14'),
(83, '2022-12-29', 28, 7, NULL, 'ফুটবল খেলোয়াড়', '16724258711672139843murobbi-akadoshpng1.webp', NULL, 'একাত্তরে সিলেটের মুরারিচাঁদ (এমসি) কলেজের বিজ্ঞান বিভাগের দ্বাদশ শ্রেণির ছাত্র ছিলেন শ্রীকান্ত দাস। ৭ মার্চ বঙ্গবন্ধু শেখ মুজিবুর রহমানের ভাষণের পর পরিস্থিতি বদলে যায়। শহর হয়ে পড়ে জনশূন্য। এ অবস্থায় শিক্ষার্থীরাও ছাত্রাবাস ছাড়েন। অন্য অনেকের মতো শ্রীকান্তও বাড়ি ফেরেন।......।।\r\n\r\nআরও পড়ুন\r\n‘আমার কিছু হবে না’ বলে বেরিয়ে গিয়েছিলেন বাবা\r\n‘আমার কিছু হবে না’ বলে বেরিয়ে গিয়েছিলেন বাবা\r\nহবিগঞ্জের আজমিরীগঞ্জ উপজেলার বদলপুর ইউনিয়নের পাহাড়পুর গ্রামে শ্রীকান্তের বাড়ি। ১৯৫২ সালে হাওরের এই প্রত্যন্ত গ্রামের এক দরিদ্র পরিবারে তাঁর জন্ম। বাবা নীলকান্ত দাস ও মা চন্দ্রময়ী দাসের চার সন্তানের মধ্যে তিনি ছিলেন দ্বিতীয়। গ্রামের বিদ্যালয়ে প্রাথমিক পর্যন্ত পড়েন। এরপর ১৯৬৯ সালে বিজ্ঞান বিভাগের শিক্ষার্থী হিসেবে বিরাট এএবিসি হাইস্কুল থেকে প্রথম শ্রেণিতে ম্যাট্রিকুলেশন পাস করেন। এরপরই ভর্তি হন এমসি কলেজে।\r\n\r\nবাড়ি ফিরে দেশের সামগ্রিক পরিস্থিতির দিকে নজর রাখেন শ্রীকান্ত। মুক্তিযুদ্ধ শুরু হলে যুদ্ধে যাওয়ার প্রস্তুতি নেন। গ্রামের আরও কয়েকজনকে মুক্তিযুদ্ধে যাওয়ার জন্য উৎসাহ দেন। পরে শ্রীকান্ত ১৭ মে গোপাল চক্রবর্তী, হরিপ্রসন্ন চক্রবর্তী ও সুশান্ত দাসকে নিয়ে ভারতের মেঘালয়ে চলে যান। ২৮ দিনের প্রশিক্ষণ শেষে দেশে ফিরে তাঁরা ৫ নম্বর সেক্টরে যোগ দেন। প্রশিক্ষণকালে শ্রীকান্তের ব্যাচ নম্বর ছিল ৬।\r\n\r\nবেশ কিছু গুরুত্বপূর্ণ অপারেশনে অংশ নেন শ্রীকান্ত দাস। ১৯৭১ সালের ২৭ নভেম্বর সুনামগঞ্জের বৈশেরপাড়া ষোলগড় ডলুরা এলাকায় সম্মুখযুদ্ধে শহীদ হন তিনি। বেয়নেট দিয়ে খুঁচিয়ে তাঁর হৃৎপিণ্ড ও চোখ তুলে নেয় পাকিস্তান সেনাবাহিনী। রাস্তায় পড়ে ছিল তাঁর লাশ। পরে ডলুরা গণকবরে তাঁকে সমাহিত করা হয়। এই গণকবরের ৪৪ নম্বর স্মৃতিস্মারকটি হচ্ছে শ্রীকান্ত দাসের।\r\n\r\nমুক্তিযুদ্ধ শেষে ধীরে ধীরে পরিস্থিতি স্বাভাবিক হয়। এমসি কলেজ ছাত্রাবাসেও ফিরতে শুরু করেন শিক্ষার্থীরা। ১৯৭২ সালের শেষ দিকে শ্রীকান্তের স্মৃতিকে স্মরণীয় করে রাখতে শিক্ষার্থীরা ‘শহীদ শ্রীকান্ত ছাত্রাবাস’ সাইনবোর্ড ছাত্রাবাসের ব্লকে সাঁটিয়ে দেন।\r\n\r\nসে সময় ছাত্রাবাসের বাসিন্দা ছিলেন রসায়ন বিভাগের স্নাতকের শিক্ষার্থী তমাল কুমার বিশ্বাস। এখন তিনি হবিগঞ্জে আইনপেশায় যুক্ত। সত্তরোর্ধ্ব তমাল জানান, শহীদ শ্রীকান্তের স্মৃতি রক্ষায় কলেজ প্রশাসনকে অনুরোধ করলে তাঁরা গুরুত্ব দেননি। ছাত্ররা সাইনবোর্ড লাগিয়ে দেওয়ার পর অবশ্য কলেজ কর্তৃপক্ষও কাগজপত্রে শহীদ শ্রীকান্ত ছাত্রাবাস নামটি বহাল রাখে।\r\n\r\nএকটি সাইনবোর্ড ছাড়া ছাত্রাবাসটিতে আর কিছুই পাওয়া যায়নি। নেই কোনো ছবি বা স্মৃতিচিহ্ন। এ নিয়ে আবাসিক শিক্ষার্থীদের আক্ষেপও আছে। এ বিষয়ে শহীদ শ্রীকান্ত ছাত্রাবাসের বর্তমান হোস্টেল সুপার জীবনকৃষ্ণ আচার্য জানান, নামকরণটুকু ছাড়া শহীদ শ্রীকান্তের কোনো স্মৃতিচিহ্ন ছাত্রাবাসে নেই।\r\n\r\nশহীদ শ্রীকান্তের গ্রামের বাড়িতে ১১ ডিসেম্বর রাতে খোঁজ নেওয়া হয়। শ্রীকান্তের বড় ভাই রতিকান্ত দাসের ছেলে সুজিত কুমার দাস (৫১) জানান, তাঁর বাবারা ছিলেন তিন ভাই। শ্রীকান্ত ছিলেন মেজ। শ্রীকান্তের বড় ভাই রতিকান্ত ২০০৯ সালে মারা যান। তবে শ্রীকান্তের ছোট ভাই উমাকান্ত দাস (৭০) জীবিত। এ ছাড়া ময়তারা দাস (৬০) নামে শ্রীকান্তের এক ছোট বোন আছেন।\r\n\r\nসুজিত বলেন, তিনি ও তাঁর চাচা উমাকান্ত কৃষিজীবী। একেবারেই অসচ্ছল পরিবারের মানুষ তাঁরা। তবে এ নিয়ে তাঁদের কোনো আক্ষেপ নেই। আক্ষেপ কেবল এই, শহীদ পরিবার হিসেবে তাঁরা কোনো ভাতা পাওয়া তো দূরের কথা, মর্যাদাটুকুও পাচ্ছেন না। শহীদ শ্রীকান্তের স্মৃতি রক্ষায়ও তেমন কোনো উদ্যোগ নেই।', '2022-12-30 12:43:48', '2023-02-17 16:54:59'),
(84, '2023-02-01', 1, 2, NULL, 'শনিবার  জরুরী মিটিং ।', '', NULL, '<p>আসছে আগামী শনিবার ০৪/০২/২০২৩ইং বাদ এশা আলোচনা সভার আহ্বান করা হচ্ছে। উক্ত সভায় আপনাদের সকলের উপস্থিতি একান্তভাবে কামনা করি।</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>আলোচ্য বিষয়ঃ</strong> উমনপুর আইটির দায়িত্ব গ্রহণ ও পরিচালনা কমিটি পুনর্গঠন এবং বর্ষপূর্তি অনুষ্টান প্রসঙ্গে।</p>\r\n\r\n<p><strong>সভার স্থানঃ</strong> উমনপুর সরকারী প্রাথমিক বিদ্যালয়।</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><ins>দাওয়াতক্রমে&nbsp;</ins></strong></p>\r\n\r\n<p>উপদেষ্টা মন্ডলী, উমনপুর আইটি।</p>', '2023-02-01 11:59:51', '2023-02-26 00:04:33'),
(85, '2023-02-04', 1, 2, NULL, 'আগামী  সোমবার মিটিং এ উপস্থিত থাকার জন্যে অনুরুদ করা হল।', '', NULL, '<p>আসসালামু আলাইকুম,<br />\r\nআশাকরি আপনারা ভালোই আছেন।.<br />\r\n<br />\r\nআসছে আগামীকাল সোমবার ০৬/০২/২০২৩ইং বাদ এশা আলোচনা সভায় আহ্বান করছি। উক্ত সভায় আপনাদের সকলের উপস্থিতি একান্তভাবে কামনা করি।<br />\r\n<br />\r\nআলোচ্য বিষয়ঃ পরিচালনা কমিটি পুনর্গঠন এবং ১৪/০২/২০২৩খ্রিঃ বর্ষপূর্তি অনুষ্টান প্রসঙ্গে।<br />\r\nসভার স্থানঃ উমনপুর সরকারী প্রাথমিক বিদ্যালয়। সময়ঃ রাত ৮ টায়।<br />\r\n<br />\r\n<strong>দাওয়াতক্রমে</strong><br />\r\n-- -- -- -- ---<br />\r\nউপদেষ্টা মন্ডলী, উমনপুর আইটি।</p>', '2023-02-06 06:52:37', '2023-06-29 17:41:47'),
(87, '2023-06-28', 1, 1, NULL, 'মুসলিম উম্মাহর বৃহৎ ধর্মীয় উৎসব ঈদুল আজহা আগামীকাল বৃহস্পতিবার।', '1687972247EID Gaho.jpg', NULL, '<p><br />\r\nউমনপুর গ্রামবাসী আগামী কাল ঈদের জামাত সকাল ৮ টায় অনুষ্ঠিত হবে। যদি বৃষ্টি হয় তাহলে উমনপুর জামে মসজিদে&nbsp;ঈদের জামাত অনুষ্ঠিত হবে।&nbsp;<br />\r\n<br />\r\nউমনপুর গ্রামের আইটি&#39;র পক্ষ থেকে সকলকে জানাই ঈদুল আজহার শুভেচ্ছা ও &quot;ঈদ মোবারক&quot;। ​​​​ঈদ মানে আনন্দ মানে খুশী।&nbsp; মা, বাবা, পরিবার, আত্মীয়-সজন ও প্রতিবেশীর সাথে ঈদ আনন্দ ভাগাভাগির মধ্য দিয়ে চমৎকার একটি ঈদ আনন্দ উৎযাপন হউক এই কামনা করি।<br />\r\n&nbsp;</p>', '2023-06-28 21:10:47', '2023-07-07 22:38:01'),
(88, '2023-06-29', 1, 2, NULL, 'উমনপুর আইটির সকলকে সভায় উপস্থিত থাকার জন্যে অনুরুদ করা হল।', '', NULL, '<p>০১/০৭/২০২৩খ্রি মিটিং প্রসঙ্গে<br />\r\n-----------<br />\r\nআসসালামু আলাইকুম,<br />\r\nআশাকরি আপনারা ভালোই আছেন।<br />\r\n<br />\r\nসম্মানিত আইটির সকল সদস্যগণ, আসছে আগামী ০১/০৭/২০২৩ খ্রিঃ শনিবার বাদ মাগরিব আলোচনা সভার আয়োজন করা হইয়াছে, উক্ত সভায় আপনাদের উপস্থিতি একান্তভাবে কামনা করি।<br />\r\n<br />\r\nআলোচ্য বিষয়: পরিচালনা কমিটি পুর্নগঠন&nbsp;, দায়িত্ব গ্রহণ ও বিবিধ বিষয় নিয়ে আলোচনা।<br />\r\n<br />\r\nসভার স্থানঃ উমনপুর সরকারী প্রাথমিক বিদ্যালয়।<br />\r\n&nbsp;</p>', '2023-06-29 17:54:40', '2023-08-26 15:00:41'),
(89, '2023-06-29', 1, 1, NULL, 'আজকে পবিত্র ঈদুল আজহা।', '1688047693UP news.jpg', NULL, '<p>আজকে পবিত্র&nbsp; ঈদুল আজহার জামাত উমনপুর জামে মসজিদে সকাল ৮ ঘটিকায় অনুষ্ঠিত হয়। উমনপুর গ্রামের সকল মুসল্লিয়ান&nbsp; এই ঈদের জামাতে অংশগ্রহন করেন। একে অন্যের সাথে ঈদের দাওয়াত&nbsp; ও আনন্দ বিনিময় করেন।&nbsp;</p>', '2023-06-29 18:08:13', '2023-08-21 00:01:17'),
(90, '2023-08-25', 1, 1, NULL, 'উমনপুর আইটির পক্ষথেকে আর্থিক সহায়তা প্রদান।', '1692960665Donation_helps.jpg', NULL, '<p>অদ্য ২৫/০৮/২০২৩ইং বাদ জুম্মা উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের মাঠে উমনপুর আইটির পক্ষথেকে অসহায় তিনটি পরিবারকে আর্থিক সহায়তা প্রদান করা হয়। উপস্থিত ছিলেন উমনপুর আইটির সদস্য বৃন্দ।</p>\r\n\r\n<p>আর্থিক সহযোগিতায় মো: মনসুর আলী (সৌদি আরব প্রবাসী)।</p>', '2023-08-25 14:51:05', '2023-08-25 14:51:05'),
(91, '2023-08-01', 1, 5, NULL, 'তাহমিদ এর কৃতিত্ব', '1693591596Screenshot_27.png', NULL, '<p>জাতীয় শিশু পুরষ্কার প্রতিযোগিতা, সিলেট ২০২২ ও ২০২৩ খ্রিস্টাব্দ ক্বেরাত প্রতিযোগিতায় উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের ছাত্র তাহমিদ আহমদ স্থানীয় পর্যায়ে ১ম, উপজেলা পর্যায়ে ১ম, জেলা পর্যায়ে ১ম এবং বিভাগীয় পর্যায়ে ২য় স্থান অর্জন করেছে।</p>\r\n\r\n<p>গ্রামের পক্ষ থেকে অভিনন্দন তাহমিদকে এবং আমরা তাহার উজ্জ্বল ভবিষ্যৎ কামনা করি।</p>', '2023-09-01 22:06:36', '2023-09-01 22:06:36'),
(92, '2023-09-14', 1, 2, NULL, 'চিকনাগুল স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্রের উদ্বোধনী অনুষ্ঠানে গ্রামের ছোট-বড় সবাইকে উপস্থিত থাকার অনুরোধ করা হইল।', '', NULL, '<p>আগামী শনিবার ১৬ সেপ্টেম্বর ২০২৩ইং &#39;চিকনাগুল স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র&#39;-এর আনুষ্ঠানিক উদ্বোধন করবেন বাংলাদেশ প্রবাসী কল্যাণ ও বৈদেশিক কর্মসংস্থান মন্ত্রী ইমরান আহমেদ। উদ্বোধনী অনুষ্ঠান বিকেল ৪ ঘটিকায় অনুষ্টিত হবে। গ্রামের ছোট-বড় সবাইকে উক্ত উদ্বোধনী অনুষ্ঠানে উপস্থিত থাকার অনুরোধ করা হইল। উক্ত উদ্বোধনী অনুষ্ঠানে উমনপুর গ্রামবাসীর উদ্যোগে শিরনি সু-ব্যবস্থাও করা হয়েছে।</p>', '2023-09-16 00:02:44', '2023-09-16 00:03:42'),
(93, '2023-09-16', 28, 3, NULL, 'চিকনাগুল স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্রের উদ্বোধনী অনুষ্ঠান।', '', NULL, '<p>গ্রামের ছোট-বড় সবাইকে উক্ত উদ্বোধনী অনুষ্ঠানে উপস্থিত থাকার অনুরোধ করা হল। ...</p>', '2023-09-16 00:07:49', '2023-09-18 10:53:23'),
(94, '2023-09-16', 1, 1, NULL, 'চিকনাগুল স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র উদ্বোধন।', '1695539171চিকনাগুল স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র.webp', NULL, '<p>১৬ সেপ্টেম্বর ২০২৩ইং&nbsp;শনিবার বিকেলে চিকনাগুল স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র উদ্বোধন করেন জাতীয় সংসদ সদস্য প্রবাসী কল্যাণ ও বৈদেশিক কর্মসংস্থান মন্ত্রী ইমরান আহমদ।&nbsp;উদ্বোধনের পর পর&nbsp; উমনপুর গ্রামের কৃতি সন্তান ও পানিছড়া মাদ্রাসার মুহতামিম মাওলানা হরমুজ আলী সাহেবের মোনাজাতের&nbsp;মধ্যদিয়ে শুরু হয়।&nbsp;প্রবাসী কল্যাণ ও বৈদেশিক কর্মসংস্থান মন্ত্রী ইমরান আহমদ&nbsp;বলেছেন, সরকার দেশের মানুষের চিকিৎসা সেবার উন্নয়নে দেশের প্রতি&#39;টি ইউনিয়ন পর্যায়ে স্বাস্থ্য সেবা কল্যাণ কেন্দ্র নিমার্ণ করে জনগণের মৌলিক চাহিদা পুরণ করে যাচ্ছেন। স্বাস্থ্য সেবা হচ্ছে মানুষের অন্যতম মৌলিক চাহিদা, শেখ হাসিনা সরকার রাষ্ট্রীয় ক্ষমতায় এসে চিকিৎসা ক্ষেত্র অগ্রাধিকার দিয়েছেন। ইউনিয়নে স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্রে গ্রাম অঞ্চলের গর্ভবতী মহিলা-শিশু সুরক্ষায় বিশেষ ভূমিকা পালন করবে। দেশের চলমান উন্নয়ন কাজ অব্যাহত রাখতে তিনি আগামী জাতীয় সংসদ নির্বাচনে শেখ হাসিনা সরকার-কে সহযোগিতা করার আহবান জানান। জৈন্তাপুর&nbsp;উপজেলা পরিষদ চেয়ারম্যান কামাল আহমদ চিকনাগুল ইউনিয়ন স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্রের রাস্তা ও ব্রিজ নির্মাণের প্রতিশ্রুতি দিয়েছেন।</p>\r\n\r\n<p>অনুষ্ঠানে সভাপতিত্ব করেন চিকনাগুল ইউনিয়ন পরিষদ চেয়ারম্যান কামরুজ্জামান চৌধুরী। অনুষ্ঠানে বিশেষ অতিথি ছিলেন উপজেলা পরিষদ চেয়ারম্যান কামাল আহমদ, উপজেলা নির্বাহী অফিসার আল-বশিরুল ইসলাম, জৈন্তাপুর মডেল থানার অফিসার (ইনচার্জ) মো: তাজুল ইসলাম (পিপিএম), সিলেট জেলা পরিবার পরিকল্পনা বিভাগের উপ-পরিচালক বিপ্লব বড়ুয়া, উপজেলা আওয়ামী লীগের সাধারণ সম্পাদক এম লিয়াকত আলী।</p>\r\n\r\n<p>উমনপুর গ্রামের সম্মানিত মুরুব্বী জনাব আব্দুল মোমেন সাহেবের পরিচালনায় অনুষ্ঠানে বক্তব্য রাখেন ও উক্ত উদ্বোধনী অনুষ্ঠানে উপস্থিত ছিলেন&nbsp;উমনপুর গ্রামের সম্মানিত মুরুব্বী জনাব মাহমুদ হোসেইন রব্বানি, মোঃ নুরুল ইসলাম, মোঃ আব্দুল লতিফ, মোঃ আয়োব আলী, মোঃ সিরাজুল ইসলাম, মোঃ&nbsp;মঈনুল হোসাইন, মোঃ মন্তাজ আলী, লালই মিয়া, উমনপুর গ্রামে ইউপি সদস্য জনাব ফারুক আহমদ, চিকনাগুল মাদ্রাসার স্মমানিত মুহতামিম মাওলানা মোঃ আব্দুল আলীম,&nbsp;চিকনাগুল ইউনিয়ন আওয়ামী লীগের সভাপতি ডা: আবুল হাসনাত চৌধুরী, সাধারণ সম্পাদক রহমত আলী, চিকনাগুল ইউনিয়ন ও উমনপুর গ্রামের ছোট - বড় সকল শ্রেণী ও পেশার মানুষ।&nbsp;</p>', '2023-09-24 11:06:11', '2023-09-24 17:49:00'),
(95, '2023-09-23', 1, 4, NULL, 'উমনপুর জামে মসজিদে নতুন সাইনবোর্ড।', '1695546639Umonpur Jame Mosque_light.webp', NULL, '<p>উমনপুর জামে মসজিদ ও&nbsp;ওজুখানায় নতুন সাইনবোর্ড লাগানো হয়েছে এবং জামে মসজিদের অত্যধুনিক ওয়াশ ব্লকের উপরে দু-তলায় মহিলাদের নামাজের সু-ব্যবস্থা করা হয়েছে।&nbsp;মহিলাদের নামাজের স্থানে আর একটি সানবোর্ড লাগানো হবে।&nbsp;</p>', '2023-09-24 13:10:39', '2023-09-24 13:10:39'),
(96, '2023-09-28', 1, 4, NULL, 'উমনপুর পাহাড় মসজিদের  বাহিরের  নকশা।', '1695985365Umonpur-pahar-mosquee.webp', NULL, '<p>উমনপুর পাহাড় মসজিদের বাহিরের নকশা। উমনপুর পাহাড় মসজিদ তিন তলা বিশিষ্ট&nbsp;নকশায় নির্মিত হবে&nbsp;এবং অতি শীঘ্রই মসজিদের নির্মাণ কাজ শুরু হবে।</p>', '2023-09-29 15:02:45', '2023-09-29 15:11:38'),
(97, '2023-10-01', 1, 2, NULL, 'আগামীকাল  উমনপুর গ্রামের সকল শিশুকে টিকা দেয়া হইবে।', '', NULL, '<p>আগামী ৮/১০/২৩ ইংরেজি তারিখে চিকনাগুল স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্রে&nbsp;এক মাস হইতে দুই বছর&nbsp; পর্যন্ত সকল শিশুকে টিকা দেওয়া হবে।</p>', '2023-10-01 14:57:02', '2023-10-08 08:50:28'),
(99, '2023-10-09', 1, 1, NULL, 'উমনপুর প্রবাসী গ্রুপ এর পক্ষ থেকে মৃত মোস্তফা মিস্ত্রির পরিবারকে  জমির দলিল হস্তান্তর।', '1696862114Onudan_mustofa.jpg', NULL, '<p>উমনপুর প্রবাসী গ্রুপ এর পক্ষথেকে মৃত মোস্তফা মিস্ত্রির পরিবারকে ৪-শতক জমির দলিল হস্তান্তর করা হয়েছে। ৪-শতক জমি ছাড়াও এক প্রবাসী সম্পূর্ণ বসতঘর তৈরীসহ আরেক প্রবাসী টিউবওয়েল স্থাপন করে দেওয়ার ওয়াদা করেছেন। এছাড়া গ্রামের যুবকদের উদ্যোগে তার পরিবারকে একটি টমটম গাড়ি কিনে দেওয়ার অঙ্গিকার করেছেন।</p>\r\n\r\n<p>উপস্থিত ছিলেন উমনপুর গ্রামের মুরুব্বি জনাব মোঃ মইনুল হোসেইন, ফারুক আহমদ, আলী আহমদ, লালই মিয়া এবং যুক্তরাজ্য প্রবাসী জনাব জিল্লুর রহমান সহ কামাল আহমদ, কায়েছুল ইসলাম, জুবের আহমদ, আব্দুল করিম, আশিক আহমদ প্রমূখ।</p>', '2023-10-09 18:35:14', '2023-10-10 22:05:59'),
(100, '2023-10-18', 65, 5, NULL, 'শেখ রাসেল দিবস উদযাপন ২০২৩', '', NULL, NULL, '2023-10-18 11:06:50', '2023-10-18 11:06:50'),
(101, '2023-10-23', 1, 2, NULL, 'উমনপুর পাহাড় মসজিদের ভিত্তিপ্রস্তর স্থাপন হবে  ২৪ অক্টোবর ২০২৩ইং তাই সবাইকে  উপস্থিত থাকার  অনুরোধ করা হইলো।', '', NULL, '<p>আগামী ২৪ অক্টোবর ২০২৩ইং সকাল ১০টায় উমনপুর পাহাড় মসজিদের ভিত্তিপ্রস্তর স্থাপন হবে। তাই আপনারা সবাইকে উপস্থিত থাকার জন্য অনুরোধ করা হইলো।&nbsp;</p>', '2023-10-23 21:58:21', '2023-10-24 09:35:40'),
(102, '2023-10-24', 1, 1, NULL, 'উমনপুর পাহাড় মসজিদের ভিত্তিপ্রস্তর স্থাপন।', '1698135052Pahar mosjid.webp', NULL, '<p>আজ&nbsp;২৪/১০/২০২৩ খ্রি.&nbsp;রোজ মঙ্গলবার বেলা সকাল ১১ঃ৩০ মিনিটে সিলেট জেলার জৈন্তাপুর উপজেলার চিকনাগুল ইউনিয়নের উমনপুর গ্রামের &quot;উমনপুর পাহাড় মসজিদ&quot;র ভিত্তিপ্রস্তর স্থাপন করা হয়। উল্লেখিত অনুষ্ঠানে উপস্থিত ছিলেন বাংলাদেশ সরকারের তথ্য মন্ত্রণালয়ের সাবেক অতিরিক্ত সচিব জনাব মোঃ মুহিবুল হোসেইন, মাদ্রাসাতুল উলুম হরিপুর বাজারের মুহতামিম শাইখ মাওলানা মোঃ হিলাল আহমদ, মুহাদ্দিস মাওলানা মোঃ আনোয়ারুল হক হরিপুর বাজার মাদ্রাসা, জামেয়া মাহমুদিয়া মায্হারুল উলূম উমনপুর মাদ্রাসার মুহতামিম, ইমাম ও খতীব উমনপুর জামে মসজিদ জনাব মোঃ ফুরকান আলী কাসেমী। এছাড়াও উমনপুর পাহাড় মসজিদের সভাপতি মোঃ আব্দুল হান্নান, সাধারণ সম্পাদক মোঃ আব্দুল মোমেন, কোষাধক্ষ্য মোঃ উসমান আলী, সদস্য জনাব নুর উদ্দিন, জনাব আব্দুল মান্নান ও জনাব মোঃ জালাল উদ্দিন। আরও উপস্থিত ছিলেন গ্রামের মুরুব্বি সর্ব জনাব মোঃ আব্দুল লতিফ, মোঃ নুরুল ইসলাম, মোঃ আইয়ুব আলী, আজাদ খান, মেম্বার ফারুক আহমদ, ইব্রাহিম আলী,&nbsp; ইঞ্জিনিয়ার কিবরিয়া সহ গ্রামের ছোট - বড় সবাই।</p>\r\n\r\n<p>উমনপুর পাহাড় মসজিদ নির্মাণে আর্থিক সাহায্যে এগিয়ে আসুন:&nbsp;<a href=\"https://umonpur.info/web-donate/show/18\">https://umonpur.info/web-donate/show/18</a></p>', '2023-10-24 12:10:52', '2023-10-24 21:09:19'),
(103, '2023-10-30', 1, 1, NULL, 'একটি শোক সংবাদ।', '1698672627download.jpeg', NULL, '<p>উমনপুর পাহাড় নিবাসী জনাব জামাল আহমদ ও ছয়ফুল আলমের এর আম্মা ইন্তিকাল করিয়াছেন, &#39;ইন্নালিল্লাহি ওয়াইন্নাইলাহি রাজিউন&#39;।</p>\r\n\r\n<p>আগামী কাল সকাল ৯ঃ৩০ মিনিটে&nbsp;উমনপুর জামে মসজিদে জানাজার নামাজ অনুষ্ঠিত হইবে, এতে আপনাদের সকলের উপস্থিতি ও দোয়া কামনা করি।</p>', '2023-10-30 17:30:27', '2023-10-30 19:21:07'),
(104, '2023-11-23', 1, 1, NULL, 'উমনপুর জামে মসজিদের হুজুরের অবস্থা গুরুতর।', '1700918405Imam sab Umonpur.jpg', NULL, '<p>সিলেট জেলার জৈন্তাপুর উপজেলার উমনপুর জামে মসজিদের দীর্ঘদিনের স্বনামধন্য ও সুযোগ্য ইমাম ও খতিব, মাদ্রাসাতুল উলুম দারুল হাদিস হরিপুর বাজার মাদ্রাসার সিনিয়র মুহাদ্দিস, উমনপুর মাযহারুল উলুম মাদ্রাসার সুযোগ্য মুহতামিম মাওলানা ফুরক্বান আলী ক্বাসিমী হুজুরের অবস্থা গুরুতর হওয়ায় সিলেট শহরের একটি বেসরকারি হাসপাতালের ICU তে আছেন। হুজুরের অবস্থা বেশি ভালো না।</p>\r\n\r\n<p>সকলকে দোয়ায় হুজুরকে স্মরণ করার অনুরোধ জানাচ্ছি।</p>\r\n\r\n<p>ইয়া আল্লাহ, হুজুরকে তোমার অসুস্থতা নামক নিয়ামত নিয়ে শিফা নামক নিয়ামত দান কর।</p>\r\n\r\n<p>আমিন।</p>', '2023-11-25 18:20:05', '2023-11-25 18:20:05'),
(105, '2023-11-25', 1, 6, NULL, 'উমনপুর মাদ্রাসা বার্ষিক ওয়াজ মাহফিল - ২০২৩', '17009188312023 jolsa banner.jpg', NULL, '<p>আগামী ১৩ ডিসেম্বর রোজ বুধবার&nbsp;জামেয়া মাহমুদিয়া মায্হারুল উলূম উমনপুর মাদ্রাসা বার্ষিক ওয়াজ মাহফিল।</p>\r\n\r\n<p>মহতি মাহফিলে দেশের খ্যাতিমান উলামায়ে কেরাম মূল্যবান নসিহত পেশ করবেন। মোবারক মাহফিলে আপনাদের দাওয়াত।</p>\r\n\r\n<p>&nbsp;</p>', '2023-11-25 18:27:11', '2023-11-25 18:28:22'),
(106, '2023-12-13', 1, 3, NULL, 'জামেয়া মাহমুদিয়া মায্হারুল উলূম উমনপুর মাদ্রাসা\'র বার্ষিক ওয়াজ মাহফিল।', '', NULL, '<p>আজ প্রিয় জামেয়া মাহমুদিয়া মায্হারুল উলূম উমনপুর মাদ্রাসা এর বার্ষিক ওয়াজ মাহফিল।</p>\r\n\r\n<p>সকলের দাওয়াত মহতি মাহফিলে</p>\r\n\r\n<p>দেশের খ্যাতি মান উলামায়ে কেরাম মূল্যবান নসিহত পেশ করবেন।</p>\r\n\r\n<p>সময় সূচীঃ</p>\r\n\r\n<p>বাদ যোহর</p>\r\n\r\n<p>হাফিজ মোহাম্মদ আলী সাহেব</p>\r\n\r\n<p>সভাপতি উলামা পরিষদ উমনপুর</p>\r\n\r\n<p>হযরত মাওলানা আজিজুর রহমান সাহেব</p>\r\n\r\n<p>মুহতামিম মারকাযুল হিদায়্যা সিলেট</p>\r\n\r\n<p>বাদ আছর</p>\r\n\r\n<p>মুফতি জিল্লুর রহমান সাহেব</p>\r\n\r\n<p>মুহতামিম দারুল উলুম হেমু মাদ্রাসা।</p>\r\n\r\n<p>বাদ মাগরিব</p>\r\n\r\n<p>হযরত মাওলানা নুরুল ইসলাম খান সাহেব সুনামগঞ্জ</p>\r\n\r\n<p>রাত ৭ টা</p>\r\n\r\n<p>হযরত মাওলানা মুফতি হাবিবুল্লাহ মাহমুদ কাসেমী ঢাকা</p>\r\n\r\n<p>রাত ৮ টা</p>\r\n\r\n<p>হযরত মাওলানা আব্দুল কাদির বাগের খালী</p>\r\n\r\n<p>রাত ৯টা</p>\r\n\r\n<p>হযরত মাওলানা মুস্তাক আহমদ খান সাহেব</p>\r\n\r\n<p>রাত ১০ টা</p>\r\n\r\n<p>হযরত মাওলানা আহমদ আলী চিল্লার হুজুর</p>\r\n\r\n<p>রাত ১১ টা</p>\r\n\r\n<p>ক্বারী তৈয়বুর রহমান সাহেব।</p>\r\n\r\n<p>সম্ভাব্য সময় সুচী!</p>', '2023-12-15 23:40:49', '2023-12-15 23:43:31'),
(107, '2023-12-10', 1, 5, NULL, 'বিদায়ী সংবর্ধনা অনুষ্ঠান ও বার্ষিক পরীক্ষার ফলাফল প্রকাশ।', '1703672993school- (1).webp', NULL, '<p>উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে ছাত্র ছাত্রীদের বার্ষিক পরীক্ষার চূড়ান্ত ফলাফল প্রকাশিত হয় ১০ ডিসেম্ভর ২০২৩ইং। শিশু হতে পঞ্চম শ্রেণী পর্যন্ত মেধা তালিকায় প্রথম, দ্বিতীয় ও তৃতীয় স্থান অর্জনকারী শিক্ষার্থীদের পুরস্কার বিতরণ সহ পঞ্চম শ্রেণীর শিক্ষার্থীদের বিদায়ী সংবর্ধনা দেওয়া হয়।</p>\r\n\r\n<p>উক্ত অনুষ্ঠানে উপস্তিত ছিলেন বিদ্যালয়ের সভাপতি জনাব মোঃ মন্তাজ আলী, সাবেক সভাপতি জনাব মোঃ আব্দুল মোমেন, ইউপি সদস্য জনাব ফারুক আহমদ, বিশিষ্ট রাজনীতিবিদ জনাব রহমত আলী সহ অত্র বিদ্যালয়ের প্রধান শিক্ষক জনাব মোঃ নুরুল ইসলাম ও বিদ্যালয়ের শিক্ষক মন্ডলীগণ।</p>', '2023-12-27 15:29:53', '2023-12-27 17:39:26'),
(108, '2023-12-25', 1, 2, NULL, 'উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে ভর্তি চলছে।', '', NULL, '<p>উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে ভর্তি হতে পারবেন যদি শিক্ষার্থীর বয়স ৫ বছর কিংবা তার উপরে হয়।&nbsp;<br />\r\n<br />\r\nভর্তি হতে যা যা লাগবেঃ</p>\r\n\r\n<p>১। শিক্ষার্থীর জন্ম নিবন্ধন সনদের অনুলিপি ১ কপি।<br />\r\n২।&nbsp;শিক্ষার্থীর পিতা মাতার জাতীয় পরিচয় পত্রের&nbsp;অনুলিপি ১ কপি।</p>\r\n\r\n<p>৩।&nbsp;২য় থেকে ৫ম শ্রেণীর ভর্তির ক্ষত্রে সংশ্লিষ্ট বিদ্যালয়ের ছাড়পত্র/ প্রত্যয়ন পত্রের মুলকপি।</p>\r\n\r\n<p>৪। মাতার জাতীয় পরিচয়পত্র দ্বারা রেজিষ্ট্রেশনকৃত সচল মোবাইল নাম্বার।</p>\r\n\r\n<p>৫। শিক্ষার্থীর দুই কপি ছবি (পাসপোর্ট সাইজ ১কপি ও স্ট্যাম্প সাইজ ১ কপি নির্ধারিত ক্যাচমেন্ট এলাকার বাসিন্দা হতে হবে। সরকারি নীতিমালা অনুযায়ী ভর্তি ফরম বিক্রি, ভর্তি ফি উত্তোলন ও ভর্তি পরীক্ষা গ্রহনযোগ্য নয়।</p>', '2023-12-29 09:08:06', '2023-12-29 18:38:44'),
(109, '2023-12-29', 1, 5, NULL, 'উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে ভর্তি চলছে। ', '1703823104notice_School.webp', NULL, '<p>উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে ভর্তি হতে পারবেন যদি শিক্ষার্থীর বয়স ৫ বছর কিংবা তার উপরে হয়।&nbsp;<br />\r\n<br />\r\nভর্তি হতে যা যা লাগবেঃ</p>\r\n\r\n<p>১। শিক্ষার্থীর জন্ম নিবন্ধন সনদের অনুলিপি ১ কপি।<br />\r\n২।&nbsp;শিক্ষার্থীর পিতা মাতার জাতীয় পরিচয় পত্রের&nbsp;অনুলিপি ১ কপি।</p>\r\n\r\n<p>৩।&nbsp;২য় থেকে ৫ম শ্রেণীর ভর্তির ক্ষত্রে সংশ্লিষ্ট বিদ্যালয়ের ছাড়পত্র/ প্রত্যয়ন পত্রের মুলকপি।</p>\r\n\r\n<p>৪। মাতার জাতীয় পরিচয়পত্র দ্বারা রেজিষ্ট্রেশনকৃত সচল মোবাইল নাম্বার।</p>\r\n\r\n<p>৫। শিক্ষার্থীর দুই কপি ছবি (পাসপোর্ট সাইজ ১কপি ও স্ট্যাম্প সাইজ ১ কপি নির্ধারিত ক্যাচমেন্ট এলাকার বাসিন্দা হতে হবে। সরকারি নীতিমালা অনুযায়ী ভর্তি ফরম বিক্রি, ভর্তি ফি উত্তোলন ও ভর্তি পরীক্ষা গ্রহনযোগ্য নয়।</p>', '2023-12-29 09:11:44', '2023-12-29 18:38:36'),
(110, '2023-12-29', 1, 2, NULL, 'পহেলা জানুয়ারী ২০২৪ইং উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের সকল শ্রেণীর শিক্ষার্থীদের কাছে  নতুন বই বিতরণ করা হবে।', '', NULL, '<p>বই উৎসব বই উৎসব !!<br />\r\nনতুন বছর, নতুন দিন। নতুন বইয়ে হোক রঙিন। উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের সকল শ্রেণীর শিক্ষার্থীদের কাছে&nbsp; নতুন বই বিতরণ করা হবে পহেলা জানুয়ারী ২০২৪ইং।&nbsp;উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের সকল&nbsp;শিক্ষার্থীকে বিদ্যালয়ে উপস্থিত থাকার অনুরুধ করা হইলো।<br />\r\n&nbsp;</p>', '2023-12-30 17:52:41', '2023-12-30 17:57:21'),
(111, '2023-12-30', 1, 1, NULL, 'পহেলা জানুয়ারী ২০২৪ইং উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে বই বিতরণ উৎসব।', '1703941759school-1.webp', NULL, '<p>বই উৎসব বই উৎসব !!<br />\r\nনতুন বছর, নতুন দিন। নতুন বইয়ে হোক রঙিন। উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের সকল শ্রেণীর শিক্ষার্থীদের কাছে&nbsp; নতুন বই বিতরণ করা হবে পহেলা জানুয়ারী ২০২৪ইং।&nbsp;উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের সকল&nbsp;শিক্ষার্থীকে বিদ্যালয়ে উপস্থিত থাকার অনুরুধ করেছেন প্রধান শিক্ষক জনাব মোঃ নুরুল ইসলাম। বই বিতরণ অনুষ্ঠানে উপস্থিত থাকবেন&nbsp;উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের ম্যানেজিং কমিটির সকল সদস্যবৃন্দ,&nbsp; শিক্ষার্থীদের অভিভাবক&nbsp;সহ উমনপুর গ্রামের মেম্বার জনাব ফারুক আহমদ উপস্থিত থাকবেন।</p>', '2023-12-30 18:09:19', '2023-12-31 02:02:46'),
(112, '2024-01-01', 1, 3, NULL, 'উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে বই উৎসব।', '', NULL, '<p>বই উৎসব, বই উৎসব!! উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের সকল শ্রেণীর শিক্ষার্থীদের কাছে&nbsp; নতুন বই বিতরণ করা হবে।</p>', '2023-12-30 18:12:39', '2023-12-30 18:12:39'),
(113, '2024-02-02', 1, 1, NULL, 'একটি শোক সংবাদ।', '1706903814ShukSongbad.jpg', NULL, '<p>উমনপুর ছড়ারপাড় নিবাসী জনাব মানিক মিয়া মুরব্বি বৃহস্পতিবার রাতে নিজ বাড়িতে ইন্তিকাল করিয়াছেন, &#39;ইন্নালিল্লাহি ওয়াইন্নাইলাহি রাজিউন&#39;।</p>\r\n\r\n<p>আজ ০২/০২/২০২৪ইং বাদ জুম্মা উমনপুর জামে মসজিদে জানাজার নামাজ অনুষ্ঠিত হইবে, এতে আপনাদের সকলের উপস্থিতি ও দোয়া কামনা করি।</p>', '2024-02-03 00:56:54', '2024-02-03 01:08:46'),
(114, '2024-02-03', 1, 1, NULL, 'উমনপুর একাদশ ক্রীড়া সংস্থার বার্ষিক বনভোজন ২০২৪ইং।', '1706944786Picnic2021.jpg', NULL, '<p>&nbsp;আপনারা জেনে আনন্দিত হবেন যে, প্রতিবারের ন্যায় এবারও উমনপুর একাদশ ক্রীড়া সংস্থার বার্ষিক বনভোজন-২০২৪&#39;র আয়োজন করা হয়েছে। উমনপুর গ্রামের সুস্থ বিনোদনপ্রেমী যুবক-তরুণদের অংশগ্রহণে আনন্দমুখর একটি বনভোজন হতে চলেছে এবারও।</p>\r\n\r\n<p>&times;&nbsp;বনভোজনের স্থান নির্ধারণ করা হয়েছে ভোলাগঞ্জ সাদা পাথর।</p>\r\n\r\n<p>&times;<strong> </strong>চাঁদা জনপ্রতি এসএসসি ব্যাচ &#39;২০১৭&#39; থেকে &#39;২০২৩&#39; বা তত সমমান বয়সী কিশোর-যুবক ৳৪০০ এবং বড়দের ক্ষেত্রে ৳৫০০ থেকে শুরু করে বেশী হবে।</p>\r\n\r\n<p>&times;চাঁদা জমা দেওয়ার শেষ তারিখ ৫ ফেব্রুয়ারি ২০২৪ইং।</p>\r\n\r\n<p>&times;চাঁদা জমা দেওয়ার স্থান মোস্তফা টেলিকম, নাজিম টেলিকম ও মারুফ স্টোর এবং জাকারিয়া আহমেদ+নাজিম উদ্দিন (পূর্বপাড়া), আশরাফ আহমেদ (পাহাড়), রুবেল আহমেদ (মেইন গেইট)</p>\r\n\r\n<p>&times; বনভোজনে যাওয়ার তারিখ ১০ ফেব্রুয়ারি ২০২৪ইং শনিবার।</p>\r\n\r\n<p><strong>প্রত্যেকের জন্যে&nbsp;বনভোজনে যা যা থাকছে।</strong></p>\r\n\r\n<p>&rarr; টি-শার্ট।</p>\r\n\r\n<p>&rarr; যাতায়াতের জন্য বাস।</p>\r\n\r\n<p>&rarr; সকালের হালকা নাস্তা ।</p>\r\n\r\n<p>&rarr; নৌকা।&nbsp;</p>\r\n\r\n<p>&rarr; দুপুরের খাবার ইত্যাদি।<br />\r\n<br />\r\nপ্রয়োজনে যোগাযোগঃ&nbsp; 01731247275 (আশিক উদ্দিন)।</p>', '2024-02-03 12:19:46', '2024-02-03 12:56:11'),
(115, '2024-02-06', 1, 2, NULL, 'উমনপুর আইটির পরিচালনা কমিটি গঠন প্রসঙ্গে।', '', NULL, '<p>আসচ্ছে আগামী ১০ ফেব্রুয়ারী ২০২৪ইং রাত ৮ ঘটিকায় উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে উমনপুর গ্রামের আইটির গুরুত্বপূর্ণ আলোচনা সভার আয়োজন করা হয়েছে এবং গুরুত্বপূর্ণ আলোচনার পরপর উমনপুর গ্রামের আইটিতে নতুন করে পরিচালনা কমিটিতে লোক নিয়োগ করা হবে। যাহারা কমিটিতে থাকতে আগ্রহী তাহারা আগামী ১০ ফেব্রুয়ারী ২০২৪ইং তারিখের মধ্যে অথবা ঐ তারিখে সভায় নিম্নে উল্লেখিত টাকা সাথে করে নিয়ে আসতে হবে।</p>\r\n\r\n<p>আলোচনা সভার আলোচ্য বিষয়ঃ</p>\r\n\r\n<p>------ ----- ---</p>\r\n\r\n<p>১। পরিচালনা কমিটিতে লোক নিয়োগ।</p>\r\n\r\n<p>২। ১৪ ফেব্রুয়ারী ২০২৪ইং উমনপুর ওয়েবসাইটের বর্ষপূর্তি অনুষ্টান প্রসঙ্গে।</p>\r\n\r\n<p>৩। বিবিধ।</p>\r\n\r\n<p>বাধ্যতামূলক মেম্বারশিপ ফি</p>\r\n\r\n<p>------------</p>\r\n\r\n<p>উপদেষ্টা মণ্ডলীগণ প্রতিবছর ১০০০টাকা করে এবং যারা পরিচালনায় আসবেন অথবা থাকবেন ২০০০টাকা করে প্রতিবছর দিতে হবে। যারা টাকা দিতে অনিচ্ছুক তাদেরকে এই কমিটিতে তালিকাভুক্ত করা হবে না।</p>\r\n\r\n<p>টাকা দিয়ে কী হবে?</p>\r\n\r\n<p>-------------</p>\r\n\r\n<p>উমনপুর গ্রামের আইটি খ্যাঁতে ব্যয় অথবা গ্রামের অসহায় মানুষকে সহায়তা বাবত অথবা গ্রামের যেকোন উন্নয়নের কাজে ব্যয় করা হবে। আশাকরি উপরিউক্ত বিষয় উমনপুর গ্রামের কল্যাণের স্বার্থে বিবেচনা করবেন এবং কোন পরামর্শ থাকলে সহযোগিতা করবেন।</p>\r\n\r\n<p>সৌজন্যে - উমনপুর আইটি।</p>', '2024-02-06 17:56:53', '2024-02-11 22:40:54'),
(116, '2024-02-09', 1, 3, NULL, 'প্রথম বারি পলো বাওয়া উৎসব ২০২৪ইং।', '', NULL, '<p>উমনপুর গ্রামে প্রতিবছরের ন্যায় ২০২৪ইং সনে দুলভ বিলে পলো বাওয়া উৎসবের আয়োজন করা হয়েছে এবং শুধু উমনপুর গ্রামের লোকজন পলো বাওয়ায় অংশগ্রহণ করিতে পারবেন।&nbsp;</p>', '2024-02-11 21:43:28', '2024-02-11 23:24:02'),
(117, '2024-02-09', 1, 2, NULL, 'আগামী কাল শনিবার প্রথম বারি পলো বাওয়া উৎসব ২০২৪ইং পালিত হবে গ্রামের সকলকে অংশগ্রহণ করার অনুরোধ করা হইলো।', '', NULL, '<p>উমনপুর গ্রামে প্রতিবছরের ন্যায় এবার ১০/০২/২০২৪ইং শনিবার উমনপুর দুলভ বিলে পলো বাওয়া উৎসবের আয়োজন করা হয়েছে।&nbsp;উমনপুর দুলভ বিলে পলো বাওয়া উৎসবে শুধু উমনপুর গ্রামের লোকজন পলো বাওয়ায় অংশগ্রহণ করিতে পারবেন।&nbsp;</p>', '2024-02-11 21:56:41', '2024-02-11 21:56:41'),
(118, '2024-02-17', 1, 3, NULL, 'দ্বিতীয় বারি পলো বাওয়া উৎসব ২০২৪ইং।', '', NULL, '<p>উমনপুর গ্রামে প্রতিবছরের ন্যায় ১৭ ফেব্রুয়ারি ২০২৪ইং সনে দুলভ বিলে পলো বাওয়া উৎসবের আয়োজন করা হয়েছে। আনন্দময় এই উৎসবে গ্রামের সকলকে অংশগ্রহণ করার জন্যে অনুরোধ করা হইল। শুধু উমনপুর গ্রামের লোকজন পলো বাওয়ায় অংশগ্রহণ করিতে পারবেন।&nbsp;</p>\r\n\r\n<p>&nbsp;</p>', '2024-02-20 23:54:05', '2024-02-24 17:39:56'),
(119, '2024-02-20', 1, 2, NULL, 'আন্তর্জাতিক মাতৃভাষা দিবস উপলক্ষে দিনব্যাপী ক্রীড়া প্রতিযোগীতা ও সাংস্কৃতিক আনুষ্ঠান প্রসঙ্গে।', '', NULL, '<p>আসছে আগামী ২১শে ফেব্রুয়ারি ২০২৪ইং রোজ বুধবার আন্তর্জাতিক মাতৃভাষা দিবস উপলক্ষে উমনপুর সরকারি প্রাথমিক বিদ্যালয় উমনপুর একাদশ ক্রীড়া সংস্থার যৌথ উদ্যোগে উমনপুর সরকাররি প্রাথমিক বিদ্যালয়র মাঠে দিনব্যাপী ক্রীড়া প্রতিযোগীতা ও সাংস্কৃতিক আনুষ্ঠানের আয়োজন করা হয়েছে।<br />\r\n<br />\r\nউক্ত আনুষ্ঠানে আপনি/ আপনারা বিশেষ ভাবে আমন্ত্রিত।<br />\r\n<br />\r\nআমন্ত্রণে<br />\r\n---------<br />\r\nউমনপুর একাদশ ক্রীড়া সংস্থা&nbsp;</p>', '2024-02-21 00:02:22', '2024-02-21 00:57:25'),
(120, '2024-02-21', 1, 1, NULL, 'আন্তর্জাতিক মাতৃভাষা দিবস উপলক্ষে দিনব্যাপী ক্রীড়া প্রতিযোগিতা ও সাংস্কৃতিক অনুষ্ঠান- ২০২৪ইং।', '170845679221February.png', NULL, '<p><em>আন্তর্জাতিক মাতৃভাষা দিবস</em>&nbsp;হল একুশে ফেব্রুয়ারি বাংলাদেশ ও পশ্চিমবঙ্গসহ সমস্ত বাংলাভাষী অঞ্চলে পালিত একটি বিশেষ দিবস। আর এই দিবসে উমনপুর একাদশ ক্রীড়া সংস্থার যৌথ উদ্যোগে&nbsp;উমনপুর সরকাররি প্রাথমিক বিদ্যালয়ের মাঠে দিনব্যাপী ক্রীড়া প্রতিযোগীতা ও সাংস্কৃতিক অনুষ্ঠানের আয়োজন করা হয়েছে। বুধবার&nbsp;২১ ফেব্রুয়ারি ২০২৪ইং&nbsp;সকাল ৮ঃ৩০ মিনিটে দিবসের কার্যক্রম উদ্বোধন হবে।&nbsp; তারপর সর্বপ্রথম দূর পাল্লার দৌড়&nbsp; আয়োজনের মধ্য দিয়ে শুরু হবে সকল ইভেন্টগুলার কার্যক্রম । পাশাপাশি ধারাবাহিকভাবে চলমান থাকবে উমনপুর সরকারি প্রাথমিক বিদ্যালয় ও গ্রামের ছাত্রছাত্রীদের সকল ইভেন্ট।&nbsp;</p>', '2024-02-21 00:19:52', '2024-02-21 18:20:46'),
(121, '2024-02-21', 1, 1, NULL, 'একটি শোক সংবাদ।', '1708523389ShukSongbad_1.jpeg', NULL, '<p>উমনপুর পাহাড় নিবাসী&nbsp;জনাব মোহাম্মদ আলী (আনিসুল মিয়া) এর আব্বা জনাব আব্দুল হক্ব সাহেব ইন্তেকাল হইয়াছেন। আগামীকাল বৃহস্পতিবার&nbsp; ২২/০২/২০২৪ইং সকাল ৯ঃ৩০ মিনিটের সময় হরিপুর মাদ্রাসা মাঠে জানাজার নামাজ অনুষ্ঠিত হইবে।</p>', '2024-02-21 18:49:49', '2024-02-21 22:56:37'),
(122, '2024-02-21', 1, 2, NULL, 'উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের ছাত্র-ছাত্রীদের উপবৃত্তি প্রসঙ্গে।', '', NULL, '<p>উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের ছাত্র-ছাত্রীদের উপবৃত্তি প্রাপ্ত সকল অভিভাবকদের&nbsp; অবগতির জন্যে জানানো যাইতেছে যে উপবৃত্তির টাকা এসেছে&nbsp; যত তাড়াতাড়ি সম্ভব টাকা উত্তলন করার জন্যে&nbsp;অভিভাবকদের&nbsp; অনুরোধ করা হইল।<br />\r\n<br />\r\nনুরুল ইসলাম<br />\r\nপ্রধান শিক্ষক<br />\r\nউমনপুর সরকারি প্রাথমিক বিদ্যালয়।</p>', '2024-02-21 21:18:23', '2024-02-21 21:18:23'),
(123, '2024-02-24', 1, 3, NULL, 'তৃতীয় বারি পলো বাওয়া উৎসব।', '', NULL, '<p>উমনপুর গ্রামে প্রতিবছরের ন্যায় ২৪ ফেব্রুয়ারি ২০২৪ইং সনে দুলভ বিলে পলো বাওয়া উৎসবের আয়োজন করা হয়েছে। আনন্দময় এই উৎসবে গ্রামের সকলকে অংশগ্রহণ করার জন্যে অনুরোধ করা হইল। শুধু উমনপুর গ্রামের লোকজন পলো বাওয়ায় অংশগ্রহণ করিতে পারবেন।&nbsp;</p>', '2024-02-24 17:39:25', '2024-04-07 10:27:43');
INSERT INTO `posts` (`id`, `date`, `user_id`, `cat_id`, `cat_sub_id`, `title`, `image`, `sub_title`, `description`, `created_at`, `updated_at`) VALUES
(124, '2024-02-25', 1, 4, NULL, 'আজ রবিবার দিবাগত রাত পবিত্র শবে বারাআত।', '1708886985murubbian.webp', NULL, '<p>হে আল্লাহ আপনি আমাদের উমনপুর গ্রামের সকল মানুষকে এই পবিত্র শবে বারাআতের উসিলায় আমাদের সবার গুনাহকে মাফ করে দিন। এই পবিত্র শবে বারাআতের উসিলায় উমনপুর গ্রামের সকল কবর বাসিকে কবরের আজাব থেকে মুক্তি দিন। আমীন ইয়া রাব্বুল আলামিন আমাদের দোয়াকে কবুল করুন এবং উমনপুর গ্রামের সকল কবর বাসিকে জান্নাতের সর্বোচ্চ মাকাম দান করুন।</p>', '2024-02-25 23:49:45', '2024-02-25 23:49:45'),
(125, '2024-02-25', 1, 1, NULL, 'উমনপুর পাহাড় মসজিদের ছাদ ঢালাই এর কাজ সম্পন্ন।', '1708887944PaharMosjid_sad_dalai.webp', NULL, '<p>উমনপুর পাহাড় মসজিদের ছাদ ঢালাই এর কাজ শুরু হয় আজকে সকাল ৮:৩০ মিনিটে।&nbsp; এতে উপস্থিত ছিলেন মাওলানা শায়েখ হিলাল আহমদ এবং স্থানীয় উলামায়ে কেরাম, মুরুব্বিয়ান, মসজিদ কমিটি ও যুব সমাজ এর যৌথ উপস্থিতিতে ছাদ ঢালাইয়ের সূচনা হয়।&nbsp;ছাদ ঢালাইয়ের সূচনার পর পর উপস্থিত&nbsp; সবাই মিলে মোনাজাত করেন। উমনপুর পাহাড় মসজিদের ছাদ ঢালাই এর কাজ&nbsp;বিকাল ৪ টারদিকে&nbsp;সফলভাবে সম্পন্ন হয়।</p>', '2024-02-26 00:05:44', '2024-02-26 00:13:56'),
(126, '2024-02-29', 1, 1, NULL, 'একটি শোক সংবাদ।', '1709175734Abdur Rahim.jpg', NULL, '<p>উমনপুর পাহাড় নিবাসী সিলেট গ্যাস ফিল্ড লিমিটেড এর প্রধান কার্যালয়ের যানবাহন শাখায় কর্মরত জনাব মো: আব্দুর রহিম সাহেব</p>\r\n\r\n<p>ইন্তেকাল করিয়াছেন &#39; ইন্নালিল্লাহি ওয়া ইন্নাইলাইহি রাজিউন&#39;।</p>\r\n\r\n<p>হে আল্লাহ আপনার বান্দাকে জান্নাতের উচ্চ মাকাম দান করুন আমিন।<br />\r\n<br />\r\nমরহুমের জানাজার নামাজ আজ বাদ যোহর হরিপুর বাজার মাদ্রাসার মাঠে সম্পন্ন করা হবে।&nbsp;এতে আপনাদের উপস্থিতি ও দোয়া কামনা করি।</p>', '2024-02-29 08:02:14', '2024-02-29 08:09:44'),
(127, '2024-04-27', 33, 5, NULL, 'উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের শ্রেণীর কার্যক্রম পরিচালনা প্রসঙ্গে', '1714217732d58ebc25-d7c5-493d-bb17-26f1aec162c6.jpeg', NULL, '<p>সকল শিক্ষার্থী ও অভিভাবকদের অবগতির জন্য জানানো যাচ্ছে যে, আগামী কাল ২৮ এপ্রিল ২০২৪ইং হতে পরবর্তি নির্দেশনা না আসা পর্যন্ত প্রাক প্রাথমিক শ্রেণী বন্ধ থাকবে এবং ১ম ও ২য় শ্রেণীর কার্যক্রম সকাল ৮:০০টা হইতে ৯:৩০ পর্যন্ত এবং ৩য় হইতে ৫ম শ্রেণীর কার্যক্রম সকাল ৯:৪৫ হইতে ১১:৩০ পর্যন্ত চলবে। তাই সকর শিক্ষার্থী কে সময় মতো বিদ্যালয়ে পাঠানোর জন্য অনুরুধ রহিলো।</p>\r\n\r\n<p>অনুরোধক্রমে -------- প্র: শি: ও ম্যানেজিং কমিটি। উমনপুর সরকারি প্রা:বি:।</p>\r\n\r\n<p><a href=\"http://www.umonpur.info/\" target=\"_blank\">www.umonpur.info</a></p>', '2024-04-27 15:35:32', '2024-04-27 15:35:32'),
(128, '2024-04-27', 1, 2, NULL, 'উমনপুর সরকারি প্রাথমিক বিদ্যালয় শ্রেণী কার্যক্রম পরিচালনা প্রসঙ্গে।', '', NULL, '<p>সকল শিক্ষার্থী ও অভিভাবকদের অবগতির জন্য জানানো যাচ্ছে যে, আগামী কাল ২৮ এপ্রিল ২০২৪ইং হতে পরবর্তি নির্দেশনা না আসা পর্যন্ত প্রাক প্রাথমিক শ্রেণী বন্ধ থাকবে এবং ১ম ও ২য় শ্রেণীর &nbsp;কার্যক্রম সকাল ৮:০০ ঘটিকা হইতে &nbsp;৯:৩০ মিনিট পর্যন্ত এবং ৩য় হইতে &nbsp;৫ম শ্রেণীর &nbsp;কার্যক্রম &nbsp;সকাল ৯:৪৫ মিনিট &nbsp;হইতে &nbsp;১১:৩০ মিনিট পর্যন্ত চলবে। তাই সকর শিক্ষার্থী কে সময় মতো বিদ্যালয়ে পাঠানোর জন্য অনুরুধ &nbsp;রহিলো।&nbsp;</p>\r\n\r\n<p>অনুরোধক্রমে<br />\r\n--------<br />\r\nপ্র: শি: ও ম্যানেজিং কমিটি।<br />\r\nউমনপুর সরকারি &nbsp;প্রা:বি:।<br />\r\nwww.umonpur.info</p>', '2024-04-27 16:53:40', '2024-04-27 17:00:22'),
(129, '2024-05-04', 1, 1, NULL, 'হিফজ বিভাগের ছাত্র  ইসমাঈল আলীকে ৮০০০টাকা হাদিয়া প্রদান।', '17148201014B26421C-12F3-4154-986B-D426CAC97271.jpeg', NULL, '<p>উমনপুর মাদ্রাসার হিফজ বিভাগের ছাত্র উমনপুর গ্রামের কৃতি সন্তান ইসমাঈল আলীকে মহাগ্রন্থ আল কোরআন থেকে সু-মধুর তিলাওয়াতের একটি ভিডিও উমনপুর গ্রামের অনলাইন প্লাটফর্মে প্রকাশিত হয়। প্রকাশিত ঐ ভিডিও দেখে ও শুনে &nbsp;মুগ্ধ হয়ে দাতা: আল আমিন(সুদান) ও জুবের মাহমুদ (উমনপুর) &nbsp;৮০০০টাকা হাদিয়া করেছেন। তাই এই বিষয়কে কেন্দ্র করে শনিবার ০৪/০৫/২০২৪ইং সকাল ১০ ঘটিকায় উমনপুর মাদ্রাসার হিফজ শাখায় অনুষ্ঠানের আয়োজন করা হয়। উক্ত অনুষ্ঠানে উপস্থিত ছিলেন উমনপুর গ্রামের মুরুব্বী জনাব আইয়ুব আলী, উমনপুর আইটির উপদেষ্টা জনাব মো: আব্দুল মোমেন, মইনুল হোসেইন, উসমান আলী ও ফারুক আহমদ। উমনপুর আইটির সদস্য জনাব আনোয়ার মাসুম ও মাওলানা আব্দুর রহিম সহ মাদ্রাসার শিক্ষক মন্ডলীগ্ণ ও মাদ্রাসার ছাত্র বৃন্দ।</p>\r\n\r\n<p>পরিচালনায়&nbsp;<br />\r\n------<br />\r\nউমনপুর আইটি।&nbsp;<br />\r\nwww.umonpur.info</p>', '2024-05-04 14:55:01', '2024-05-04 16:48:10'),
(130, '2024-05-06', 1, 2, NULL, 'উমনপুর সরকারি প্রাথমিক বিদ্যালয় শ্রেণীর কার্যক্রম যথারীতি  চলবে।', '', NULL, '<p>৭ মে হইতে আগের &nbsp;মতো শিশু &nbsp;শ্রেণী সহ সকল &nbsp;শ্রেণীর কার্যক্রম যথারীতি &nbsp;চলবে, তাই সকল শিক্ষার্থীদের যথা সময়ে &nbsp;বিদ্যালয়ে পাঠানোর জন্য অনুরুধ রহিলো।</p>', '2024-05-08 10:40:35', '2024-06-29 10:41:49'),
(131, '2024-06-14', 1, 1, NULL, 'জনাব মইনুল হোসেইন আর আমাদের মাঝে নেই।', '1718342426C7FE0996-40CE-4EA8-B520-9B7CC7216F2F.jpeg', NULL, '<p>&#39;ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন&#39;</p>\r\n\r\n<p>উমনপুর গ্রামের স্বনামধন্য মুরব্বি ও উমনপুর আইটির সম্মানিত উপদেষ্টা জনাব মইনুল হোসেইন আয়ানি &nbsp;এক মর্মান্তিক সড়ক দুর্ঘটনায় ইন্তেকাল করিয়াছেন - &#39;ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন&#39;।</p>\r\n\r\n<p>মরহুমের শোক-সন্তপ্ত পরিবারের সদস্যদের প্রতি গভীর সমবেদনা ও সহমর্মিতা জ্ঞাপন এবং পরম করুণাময় &nbsp;অসীম দয়ালু আল্লাহু্ তায়ালার নিকট তাঁর বিদেহী আত্মার শান্তি ও মাগফিরাত কামনা করি।</p>', '2024-06-14 09:20:26', '2024-06-16 11:59:39'),
(132, '2024-06-16', 1, 4, NULL, 'আমরা গভীরভাবে শোকাহত', '1718534487Moinul Islam.webp', NULL, '<p>মরহুম মইনুল হোসেইন আয়ানি সাহেবের মৃত্যুতে আমরা গভীরভাবে শোকাহত। আমরা উনার আত্মার মাগফিরাত কামনা করি।</p>\r\n\r\n<p>&#39;মানুষ মরণশীল&#39;</p>\r\n\r\n<p>মরহুম মইনুল হোসেইন আয়ানি সাহেবে উমনপুর আইটির অত্যন্ত গুরুত্বপূর্ণ একজন ব্যাক্তি ছিলেন। তাহার গুরুত্বপূর্ণ ভূমিকায় উমনপুর আইটির প্ল্যাটফর্ম সু-সংগঠিত ও অনলাইনে দৃশ্যমান। শুধু তাই না উমনপুর গ্রামের প্রত্যেক বিষয়ে উনার গুরুত্ব অপরিসীম। বিশেষ করে আমরা যেই গ্রামে ছোট থেকে বড় হয়েছি সেই গ্রামের জন্য এবং ভবিষ্যৎ প্রজন্মের জন্যে জীবীত থাকা অবস্থায় কিছু না কিছু উন্নয়নমূলক কাজ করে যেতে পারি এই প্রতিজ্ঞা করা উচিৎ।</p>', '2024-06-16 14:41:27', '2025-01-21 17:30:45'),
(133, '2024-06-17', 1, 1, NULL, 'ঈদুল আজহা মোবারক!', '1718586451Eid-mubarak.webp', NULL, '<p>ঈদ মানে খুশি, ঈদ মানে আনন্দ, ঈদ আসে ভুলিয়ে দিতে সকল বিভেদ দ্বন্দ্ব, ঈদ মানে ভুলে যাওয়া যতো দুঃখ ভয়,&nbsp; ঈদের আনন্দে ভরে উঠুক উমনপুর গ্রামের প্রতিটি ঘরবাড়ি।&nbsp;কোরবানি হলো ঈশ্বরের প্রতি ভালোবাসার প্রকাশ, আল্লাহ আপনার কোরবানি কবুল করুন এবং আপনার বান্দাকে সুখ, সমৃদ্ধি ও শান্তি দান করুন।<strong>&nbsp;</strong>&nbsp; আল্লাহ আমাদের সকলের পাপ ক্ষমা করুন এবং আমাদের জীবনকে সুখে-শান্তিতে পরিপূর্ণ করুন।</p>\r\n\r\n<p>ঈদুল আজহা, যা &#39;কুরবানির ঈদ&#39; নামেও পরিচিত, মুসলিমদের জন্য একটি পবিত্র ধর্মীয় উৎসব। হজরত ইব্রাহীম (আ.) ও তাঁর পুত্র হজরত ইসমাইল (আ.)-এর আত্মত্যাগের স্মরণে এই ঈদ পালিত হয়। ঈদুল আজহা মুসলিমদের ঈমান, আত্মত্যাগ ও ঈশ্বরের প্রতি কৃতজ্ঞতার পরীক্ষা।<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>ঈদের তাৎপর্য:</strong></p>\r\n\r\n<ul>\r\n	<li><strong>আত্মত্যাগ:</strong>&nbsp;হজরত ইব্রাহীম (আ.)-এর ঘটনা আমাদের শেখায় যে ঈশ্বরের ইচ্ছার জন্য সবচেয়ে প্রিয় জিনিসও ত্যাগ করতে হয়।</li>\r\n	<li><strong>ভ্রাতৃত্ব:</strong>&nbsp;ঈদুল আজহা মুসলিমদের মধ্যে ভ্রাতৃত্ব ও ঐক্যের বন্ধনকে শক্তিশালী করে।</li>\r\n	<li><strong>কৃতজ্ঞতা:</strong>&nbsp;আল্লাহর দেওয়া সকল نعم তের জন্য কৃতজ্ঞতা প্রকাশ করা।</li>\r\n	<li><strong>দানশীলতা:</strong>&nbsp;ঈদুল আজহায় অভাবীদের মাংস বিতরণ করা হয়, যা দানশীলতা ও সহানুভূতির মনোভাবকে উৎসাহিত করে।</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>ঈদের রীতিনীতি:</strong></p>\r\n\r\n<ul>\r\n	<li>ঈদের দিন সকালে গোসল করে নতুন পোশাক পরা।</li>\r\n	<li>ঈদের নামাজ আদায় করা।</li>\r\n	<li>কোরবানি দেওয়া।</li>\r\n	<li>আত্মীয়স্বজন ও বন্ধুবান্ধবের সাথে দেখা করা এবং খাবার শেয়ার করা।</li>\r\n	<li>ঈদের আনন্দে মাতোয়রা হওয়া।</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>সৌজন্যে</strong><br />\r\n-----------<br />\r\nউমনপুর আইটি<br />\r\nwww.umonpur.info</p>', '2024-06-17 05:07:31', '2024-06-17 05:07:31'),
(134, '2024-06-21', 1, 1, NULL, 'বন্যায় ক্ষতিগ্রস্ত মানুষকে ত্রাণ বিতরণ', '1719083661tran-1.webp', NULL, '<p>আপনারা নিশ্চয়ই জানেন যে সিলেটে বন্যার অবস্তা বয়াবহ। উমনপুর গ্রামের পূর্বাঞ্চল বন্যায় তলীয়ে যাওয়ায় উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে বন্যায় ক্ষতিগ্রস্ত মানুষের জন্যে আশ্রয়কেন্দ্র খোলা হয়। আশ্রয়কেন্দ্রে যারা এসেছেন তাদের জন্যে ক্ষুদ্র পরিসরে দুই ধাপে&nbsp; ত্রাণ বিতরণ করা হয়। ত্রাণ বিতরণের সময় উপস্তিত ছিলেন উমনপুর গ্রামের মেম্বার জনাব ফারুক আহমদ ও মহিলা মেম্বার সহ গ্রামের যুব সমাজের উপস্তিতে ত্রাণ বিতরণ করা হয়।</p>', '2024-06-22 23:13:22', '2024-06-22 23:14:21'),
(135, '2024-06-26', 1, 1, NULL, 'নিখোঁজ সংবাদ', '1719469380Al Amin_nikhuj.jpg', NULL, '<p>২৬/০৬/২০২৪ ইংরেজি রোজ বুধবার সকাল ৯টার সময় নিজ বাড়ি থেকে মাদ্রাসায় যাওয়ার পথে নিখোঁজ হয়। <img alt=\"😥\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t91/1/16/1f625.png\" style=\"height:16px; width:16px\" /></p>\r\n\r\n<p>সে উমনপুর মাদ্রাসার হিফজ শাখার ছাত্র নাম &quot;আল আমীন আহমদ&quot; হারিয়েছে তাহার পিতার নাম মানিক মিয়া।</p>\r\n\r\n<p>ঠিকানাঃ উমনপুর (পাহাড়), চিকনাগুল, জৈন্তাপুর, সিলেট।</p>\r\n\r\n<p>যদি কোন হৃদয়বান ব্যাক্তি তাহার সন্ধান পেয়ে থাকেন। তাহলে নিচে দেওয়া নম্বারে যোগাযোগ করার অনুরোধ রইলো।</p>\r\n\r\n<p>01753221836</p>\r\n\r\n<p>01714956465</p>\r\n\r\n<p>01738112519</p>\r\n\r\n<p>01735647920</p>\r\n\r\n<p>বিস্তারিত দেখুনঃ <a href=\"https://l.facebook.com/l.php?u=http%3A%2F%2Fwww.umonpur.info%2F%3Ffbclid%3DIwZXh0bgNhZW0CMTAAAR1bv9Yb0whObI9Wi2n0LSLI9pYRIkwoo2f-4bMNA-0n9rTBM42sbai30ao_aem_yUdmkXKHU4M67Yczw2VYbA&amp;h=AT0VW71z_zBJF7wsERqfKOE9gVXfmAw07dMYeqaX-EWf4WwygjwWcUbc9B6zfUtRZc0F_utEtV_d1LLsHrKFnIyEsNcLqoLLW9iJtlZoA6nj2fFXjV99qI362HmlKMWKOyY0&amp;__tn__=-UK-R&amp;c[0]=AT0ptw6n-DeZfNz9E3_JBkqKEvfUSxaUGj0HeS-k1eVp3xqJWlPiA-EO1Cd-XP_2-XyuIUS7XAtBp4UaIsEsi011jO-GccofKABY2sHDgZBUoRk4bwgqM-bvtJHkwKM1AUzyH7R-TEW4Dg5YsB2Bdd5O2-6qzbjCsfz-jSi-j4q5vJMa7J5lL3riWcQGBl6bloukpJUuDg\" target=\"_blank\">www.umonpur.info</a></p>\r\n\r\n<p>ঐ ছেলের তিলাওয়াত শুনতে নিচে দেওয়া লিঙ্ক ভিজিট করুনঃ</p>\r\n\r\n<p>---------------------------</p>\r\n\r\n<p>ফেইসবুকঃ <a href=\"https://fb.watch/sYKSD_SnPc/?fbclid=IwZXh0bgNhZW0CMTAAAR3wLxqazjLvpUUZfy1IVPC552j6bZ4U4ovERYeaqJ0nlcToCVsfYhIkdBw_aem_QmGEDmm3jHVtHEcNamNYWg\" target=\"_blank\">https://fb.watch/sYKSD_SnPc/</a></p>\r\n\r\n<p>ইউটিউবঃ <a href=\"https://youtu.be/6tvkxik3Z6E?fbclid=IwZXh0bgNhZW0CMTAAAR3wLxqazjLvpUUZfy1IVPC552j6bZ4U4ovERYeaqJ0nlcToCVsfYhIkdBw_aem_QmGEDmm3jHVtHEcNamNYWg\" target=\"_blank\">https://youtu.be/6tvkxik3Z6E</a></p>', '2024-06-27 10:23:00', '2024-06-27 11:58:03'),
(136, '2024-07-03', 1, 2, NULL, 'উমনপুর সঃ প্রাঃ বিঃ এর সকল ছাত্র ছাত্রীকে অভিবাবকগণ বিদ্যালয়ে পাঠানোর জন্যে অনুরোধ করা হইলো।', '', NULL, '<p>ঈদুল আজহা ও গ্রীষ্মকালীন দীর্ঘ &nbsp;ছুটির &nbsp;পর ৩/৭/২০২৪ ইংরেজী হতে বিদ্যালয় খোলা। বিদ্যালয়ে &nbsp;শিক্ষার্থীদের উপস্থিতি কম থাকায় সকল শিক্ষার্থী কে বিদ্যালয়ে পাঠানোর জন্য অভিভাবকদের &nbsp;প্রতি অনুরোধ করা হইলো।&nbsp;</p>\r\n\r\n<p>অনুরোধ ক্রমে<br />\r\n-------&nbsp;<br />\r\nপ্রধান শিক্ষক ও স্কুল কমিটি<br />\r\nউমনপুর সরকারি&nbsp;&nbsp;প্রাথমিক&nbsp;বিদ্যালয়</p>', '2024-07-04 10:47:37', '2024-07-04 10:50:08'),
(137, '2024-07-05', 1, 2, NULL, 'ত্রাণ বিতরণ প্রসঙ্গে', '', NULL, '<p>আসসালামু আলাইকুম,<br />\r\nআশাকরি আপনারা ভালোই আছেন।</p>\r\n\r\n<p>আসচ্ছে আগামী শনিবার ০৬/০৭/২০২৪ইং তারিখে সকাল ১০ ঘটিকায় উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে নিম্নে তালিকাভুক্ত ৫৫টি পরিবারকে ত্রাণ বিতরণ করা হইবে। নিচের তালিকাভুক্ত সকল ব্যক্তিকে উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে যথা সময়ে ত্রাণ সংগ্রহ করার জন্যে অনুরোধ করা হইলো।</p>\r\n\r\n<p><strong>ত্রাণ দাতাঃ</strong> জনাব মোঃ ইব্রাহীম ( যুক্তরাজ্য প্রবাসী) উমনপুর আইটির অন্যতম উপদেষ্টা জনাব খয়রুল ইসলাম সাহেবের ভাগ্না।</p>\r\n\r\n<p><a href=\"http://www.umonpur.info/?fbclid=IwZXh0bgNhZW0CMTAAAR0cO7tqyN-5QJVIy2HwyHY5wiBv8dVgnJffYCrxgbO9HMJTibbk2cFLwC0_aem_gdkfA94uJsnfVOzGWY9Qbg\" target=\"_blank\">www.umonpur.info</a></p>', '2024-07-05 14:48:51', '2024-07-05 22:53:19'),
(138, '2024-07-06', 1, 1, NULL, 'উমনপুর গ্রামে শতাদিক পরিবারকে ত্রাণ বিতরণ', '1720264413tran.webp', NULL, '<p>আজ শনিবার ০৬/০৭/২০২৪ইং সকাল ১০ ঘটিকা হইতে উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে উমনপুর গ্রামে শতাদিক অসহায় পরিবারকে ত্রাণ বিতরণ করা। ত্রাণ বিতরণ কালীন সময় উমনপুর গ্রামের ময়মুরুব্বি, উমনপুর আইটির উপদেষ্টা মণ্ডলীগণ, উমনপুর আইটি পরিচালনা পরিষদের সদস্য সহ উমনপুর গ্রামের যুব সমাজের উপস্থিতিতে এই পরিবার গুলোকে ত্রাণ সামগ্রী প্রধান করা হয়।</p>\r\n\r\n<p><strong>ত্রাণ দাতাঃ</strong> জনাব ইব্রাহিম আলী ( যুক্তরাজ্য প্রবাসী )</p>\r\n\r\n<p>বিস্তারিতঃ <a href=\"http://www.umonpur.info/?fbclid=IwZXh0bgNhZW0CMTAAAR1Br34zV1KVcCWHu-VCRExOi8BYpxs4luWkJcdy1cYCx47hRAnPGthB8GI_aem_EFTkMJL37BwaHmxjHViYzA\" target=\"_blank\">www.umonpur.info</a><br />\r\n.<br />\r\n.<br />\r\n.</p>\r\n\r\n<p><a href=\"https://www.facebook.com/hashtag/umonpur?__eep__=6&amp;__cft__[0]=AZXn9wexxPEjScPbUTKk2a96wZjO19v9xOmwKtI8dv6nbWgY5Bhkk4OMt4PT3diEQuf5b9uQjY58uPwgBP2Sr9ZaPINdcFivcKiIsEnPZgJ1ybmwLpN_UAspK14XxW9vLVjMW-l0SPN_ayoS2ML_EwoaTyyk1WAd1Qmx2HCdfcy_40NV46SUT5fAsaOBAqFkU0-RraYCQdiRkLrAqFM0Xg3H&amp;__tn__=*NK-R\">#umonpur</a> <a href=\"https://www.facebook.com/hashtag/%E0%A6%89%E0%A6%AE%E0%A6%A8%E0%A6%AA%E0%A7%81%E0%A6%B0?__eep__=6&amp;__cft__[0]=AZXn9wexxPEjScPbUTKk2a96wZjO19v9xOmwKtI8dv6nbWgY5Bhkk4OMt4PT3diEQuf5b9uQjY58uPwgBP2Sr9ZaPINdcFivcKiIsEnPZgJ1ybmwLpN_UAspK14XxW9vLVjMW-l0SPN_ayoS2ML_EwoaTyyk1WAd1Qmx2HCdfcy_40NV46SUT5fAsaOBAqFkU0-RraYCQdiRkLrAqFM0Xg3H&amp;__tn__=*NK-R\">#উমনপুর</a></p>', '2024-07-06 15:13:33', '2024-07-06 15:13:33'),
(139, '2024-07-07', 1, 1, NULL, 'QR Code স্ক্যান করে সেকেন্ডেই ভিজিট করুন!', '1720359877umonpur-qr-code-link-2.webp', NULL, '<p>আপনার মোবাইল দিয়ে QR Code স্ক্যান করে খুব সহজে মুহূর্তেই উমনপুর গ্রামের সকল অনলাইন প্লাটফর্ম ভিজিট করতে পারেন। QR Code এর ফটো এই লিঙ্কে&nbsp;<a href=\"https://prnt.sc/-95yt76me_7n\">https://prnt.sc/-95yt76me_7n</a> দেওয়া হয়েছে। আপনারা চাইলে প্রিন্টাউট করে সংরক্ষণ করে রাখতে পারেন।</p>\r\n\r\n<p><strong>QR Code স্ক্যান করে কী ভাবে?</strong></p>\r\n\r\n<p>আপনাদের মোবাইল ফোনের ক্যামেরা অন করে ঐ QR Code এর দিকে ধরবেন দেখবেন QR Code স্ক্যান করে লিঙ্ক ডিটেক্ট করেছে এবং ঐ লিঙ্ক স্ক্রিনে সাজেস্ট করতেছে সাজেস্টেড লিঙ্কে ক্লিক অথবা টাচ দিলেই আপনার কাঙ্কিত লিঙ্কে নিয়ে যাবে।</p>\r\n\r\n<p>QR Code স্ক্যানে যাদের ফোন কাজ করছে না তাদের জন্যে করণীয় হচ্ছে ফোনের সেটিং এ যেয়ে QR Code স্ক্যানার অপশন অন করে দিবেন তারপর কাজ করবে। আর ঐ অপশন খোজে না পেলে QR Code স্ক্যানার অ্যাপ Andriod হলে Google Play Sote OR iPhone হলে Apple Store থেকে ডাউনলোড করে নিবেন।</p>\r\n\r\n<p>ধন্যবাদ</p>', '2024-07-07 17:44:37', '2024-07-10 12:50:15'),
(140, '2024-07-10', 1, 2, NULL, '১০ জুলাই ২০২৪ইং এশার নামাজের পর জামাল আব্দুন নাসের এর বাড়িতে জমায়েতে উপস্থিত থাকার অনুরোধ করা হইলো ।', '', NULL, '<p>সম্মানিত উমনপুর গ্রামবাসী.. আপনারা নিশ্চয়ই অবগত আছেন যে, পূর্ব নির্ধারিত সূচি অনুযায়ী আজ বুধবার বাদ এশা আমাদের গ্রামের যুবসমাজের উদ্যোগে একটি জমায়েত অনুষ্ঠিত হবে। তবে বৈরী আবহাওয়া বিবেচনা তথা জমায়েতে আগত গ্রামবাসীর আসন বিন্যাসের সুবিধার্থে কায়েস ভাইর বাড়ি আজকের কার্যক্রম হবে। সবাই নিজ নিজ দায়িত্বে আশেপাশের সবাইকে দাওয়াত দিয়ে বাদ এশা উপস্থিত থাকবেন। ধন্যবাদ<br />\r\n<br />\r\nউমনপুর গ্রামবাসীর জমায়েত<br />\r\nবুধবার, ১০ জুলাই ২০২৪ইং<br />\r\n<strong>স্থান: জামাল আব্দুন নাসের এর বাড়ি।</strong></p>', '2024-07-09 22:20:08', '2024-07-10 13:41:31'),
(141, '2024-07-14', 1, 2, NULL, '১৮/০৭/২০২৪ইং বাদ এশা উমনপুর জামে মসজিদে জমায়েতে উপস্তিত থাকার অনুরোধ করা হইলো।', '', NULL, '<p>আসসালামু আলিকুম, প্রিয় গ্রাম বাসি আসছে আগামী বৃহস্পতিবার ১৮ জুলাই ২০২৪ইং বাদ এশা উমনপুর গ্রামে যুবসমাজের উদ্যোগে এক জমায়েত আয়োজন করা হয়েছে। উক্ত জমায়েতে গ্রামের সমসাময়িক বিষয় নিয়ে গুরত্বপূর্ণ আলাপ আলোচনা থাকায় গ্রামের সর্বস্তরের জনগণকে উপস্থিতি থাকার অনুরোধ করা হইলো। আপনারা যারা এই নোটিশ খেয়াল করেছেন জেনেছে অন্যদেরকে জানিয়ে দেওয়ার অনুরোধ করা হলো।<br />\r\n<br />\r\n<strong>সভার স্থানঃ উমনপুর জামে মসজিদ।</strong></p>', '2024-07-14 20:52:36', '2024-07-14 21:00:23'),
(142, '2024-07-19', 1, 1, NULL, 'হারুনুর রশিদ আর আমাদের মাঝে নেই।', '1722696350Harun Chaha.jpg', NULL, '<p><br />\r\nউমনপুর গ্রামের মেম্বার জনাব ফারুক আহমদ সাহেব এর বড় ভাই&nbsp; হারুনুর রশিদ সাহেব ১৯/০৭/২০২৪ইং ইন্তেকাল করেন।<br />\r\n<br />\r\n&lsquo;ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন&rsquo;<br />\r\n<br />\r\nআমরা মরহুমের আত্মার মাগফিরাত কামনা করি।&nbsp;</p>', '2024-08-03 18:43:53', '2024-08-07 06:41:20'),
(143, '2024-08-01', 1, 2, NULL, '৪ আগষ্ট হতে উমনপুর সরকারি প্রাথমিক বিদ্যালয়  খোলা।', '', NULL, '<p>ঊর্ধ্বতন কর্তৃপক্ষের&nbsp;নির্দেশ মতে আগামী রবিবার ৪ আগষ্ট ২০২৪ইং হতে উমনপুর সরকারি প্রাথমিক বিদ্যালয়ে সকল শ্রেণীর পাঠদান যথারীতি চলবে, তাই উমনপুর সরকারি প্রাথমিক বিদ্যালয়ের&nbsp;সকল শিক্ষার্থী কে যথা সময়ে বিদ্যালয়ে পাঠানোর জন্য সকল অভিভাবকদের প্রতি অনুরোধ করছি।<br />\r\n<br />\r\nপ্রধান শিক্ষক<br />\r\nউমনপুর সরকারি প্রাথমিক বিদ্যালয়</p>', '2024-08-03 19:06:55', '2024-08-03 19:06:55'),
(144, '2024-07-13', 1, 2, NULL, 'জামেয়া মাহমুদিয়া মাযহারুল উলূম   ৪ টি বৃত্তি পেয়েছে', '1729150334Madrasha Vitti.jpg', NULL, '<p>জামেয়া মাহমুদিয়া মাযহারুল উলূম উমনপুর মাদ্রাসায় মুশাহিদিয়া বোর্ডে সালিস জামাতে ৪ টা বৃত্তি পেয়েছে!<br />\r\nলিঙ্কঃ&nbsp;https://prnt.sc/PvMRPv3i01-G</p>', '2024-10-17 11:32:14', '2024-10-17 11:32:57'),
(145, '2024-08-14', 1, 1, NULL, 'উমনপুর মাদ্রাসায় প্রথম সাময়িক পরিক্ষা শুরু হয়েছে।', '1729151074Madrasha Student_2.jpg', NULL, '<p>আজ ১৪ আগষ্ট ২০২৪ইং&nbsp;জামেয়া মাহমুদিয়া মায্হারুল উলূম উমনপুর মাদ্রাসায় প্রথম সাময়িক পরিক্ষা চলছে। এই পরীক্ষা</p>\r\n\r\n<p>আজ ১৪ আগষ্ট ২০২৪ইং থেকে ১৯ আগষ্ট ২০২৪ইং পর্জন্ত&nbsp;চলবে।</p>', '2024-10-17 11:44:34', '2024-10-17 11:44:34'),
(146, '2024-10-13', 1, 2, NULL, 'আগামী ১৪ আগষ্ট ২০২৪ইং উমনপুর মাদ্রাসার সকল ছাত্র-ছাত্রীদেরকে  প্রথম সাময়িক পরিক্ষার প্রস্তুতি নিয়ে আসার জন্যে অনুরোধ করা হইলো।', '', NULL, '<p>উমনপুর মাদ্রসার সকল ছাত্র-ছাত্রীদের অবগতির জন্যে জানানু যাচ্ছে যে, আগামী ১৪ আগষ্ট ২০২৪ইং&nbsp; জামেয়া মাহমুদিয়া মায্হারুল উলূম উমনপুর মাদ্রাসায় প্রথম সাময়িক পরিক্ষা অনুষ্ঠিত হবে।&nbsp;প্রথম সাময়িক পরিক্ষা&nbsp;১৪ আগষ্ট ২০২৪ইং থেকে ১৯ আগষ্ট ২০২৪ইং পর্জন্ত চলবে।&nbsp;মাদ্রাসার সকল&nbsp;ছাত্র-ছাত্রীদের যথা সময়ে পরীক্ষা কেন্দ্রে উপস্থিত থাকার জন্যে অনুরোধ করা হইলো।<br />\r\n<br />\r\nমিসবাহ উদ্দিন সুমন<br />\r\nজামেয়া মাহমুদিয়া মায্হারুল উলূম</p>', '2024-10-17 12:05:14', '2024-10-17 12:06:07'),
(147, '2024-09-16', 1, 1, NULL, 'উমনপুর প্রাথমিক বিদ্যালয়ের সাবেক প্রধান শিক্ষক মোহাম্মদ হুমায়ূন কবির', '1729155600Screenshot (30).png', NULL, '<p>উমনপুর সরকারী প্রাথমিক বিদ্যালয় জৈন্তাপুর উপজেলার ৬নং চিকনাগুল ইউনিয়নের উমনপুর গ্রামের এক অন্যতম শিক্ষা প্রতিষ্ঠান। ইহা ২০০০খ্রিঃ স্থাপিত হয়। স্থায়ী রেজিঃ-১১/০৮/২০১১খ্রিঃ এবং স্থায়ী জাতীয় করন-০৬/১০/২০১৩খ্রিঃ। যাত্রারম্ভে ইহা একটি বেসরকারী প্রতিষ্ঠান ছিল কিন্তু প্রবর্তীকালে সরকারি বিদ্যালয় পরিণত হয়।<br />\r\n<br />\r\nউমনপুর প্রাথমিক বিদ্যালয়ের সাবেক প্রধান শিক্ষক মোহাম্মদ হুমায়ূন কবির, পিতা জনাব আবুল কালাম, গ্রাম বড়খেরী, উপজেলা রামগতি, জেলা লক্ষীপুর।&nbsp;মোহাম্মদ হুমায়ূন কবির&nbsp; তিনি&nbsp;২০০২ সালে উমনপুর বেসরকারী প্রাথমিক বিদ্যালয়ে &nbsp;যোগদান করেন। তিনি ২০০২ইং সন থেকে ২০১২ইং সন পর্যন্ত&nbsp;নিষ্ঠার সাথে&nbsp;উমনপুর বেসরকারী প্রাথমিক বিদ্যালয়ে দায়িত্ব পালন করেন। তাহার শিক্ষকতার ধরন ও আচার ব্যবহারে একজন আদর্শ ব্যক্তি হিসেবে তিনি উমনপুরে পরিচিত ছিলেন। দীর্ঘদিন উমনপুর স্কুলের দায়িত্বপালন করা এই শিক্ষক অত্র এলাকায় প্রাথমিক শিক্ষার বিস্তারে বেশ পরিশ্রম করেছেন। উনার আন্তরিক প্রচেষ্টার কথা এলাকার কমবেশি সবাই জানেন।</p>\r\n\r\n<p>মোহাম্মদ হুমায়ূন কবির ২০২৩ইং সনের ডিসেম্বর মাসে হৃদরোগে আক্রান্ত হয়ে মৃত্যুবরণ করেন, &#39;ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন&#39;।</p>', '2024-10-17 12:53:38', '2024-10-17 13:00:00'),
(148, '2024-10-09', 86, 1, NULL, 'মইনুল হোসেন আয়ানীকে ‘হত্যার’ ঘটনায় মামলায় আসামি করা হয়েছে ৯ জনকে', '1729158811Criminal of Ayani chacha.jpg', NULL, '<p>সিলেট গ্যাসফিল্ডস লিমিটেড এর উপ-ব্যবস্থাপক, উমনপুর গ্রামের স্বনামধন্য মুরুব্বী ও উমনপুর আইটির গুরুত্বপূর্ণ উপদেষ্টা জনাব মইনুল হোসেন আয়ানী ১৩ জুন ২০২৪ইং রাতে&nbsp;উমনপুর গ্রামে সিলেট গ্যাস ফিল্ডের ৮নং কূপের গেইটের সামনে সিলেট তামাবিল রোডে আসামীরা অত্যন্ত&nbsp; সু-পরিকল্পিতভাবে&nbsp;নিহত করে।&nbsp;এতে নিহতের ভাই নজমুল হোসাইন (এমদাদ) বাদী হয়ে সিলেট জুডিসিয়াল ম্যাজিস্ট্রেট&nbsp; আদালতে মামলায় দায়ের করেন। আদালতের নির্দেশে ( ৩ অক্টোবর ২০২৪ইং)&nbsp; জৈন্তাপুর মডেল থানা মামলাটি আমলে নিয়ে রেকর্ড ভুক্ত করেছে।</p>\r\n\r\n<p>উল্লেখিত আসামীদের নাম ও বিস্তারিত পড়তে&nbsp;নিচে দেওয়া লিঙ্কে ভিজিট করুন -<br />\r\n&nbsp;<br />\r\n১।&nbsp;<a href=\"https://cutt.ly/EeSb6vfP\">www.sylhetview24.news</a><br />\r\n২।&nbsp;<a href=\"https://cutt.ly/meSb6DUU\">www.sylnewsbd.com</a></p>\r\n\r\n<p>৩।&nbsp;<a href=\"https://cutt.ly/meSb6DUU\">www.sylhetprothidin24.com</a>&nbsp;</p>', '2024-10-17 13:53:31', '2024-10-17 17:36:17'),
(150, '2024-10-10', 1, 1, NULL, 'ফ্রেন্ডস স্টাফ স্পোর্টিং ক্লাব এর ১৪ বছর পূর্তি উৎযাপন', '1729181769ফ্রেন্ডস স্টাফ স্পোর্টিং ক্লাব_1.webp', NULL, '<p>ফ্রেন্ডস স্টাফ স্পোর্টিং ক্লাব&nbsp;স্থাপিত হয় ১০/১০/২০১০ইং সনে।&nbsp;ফ্রেন্ডস স্টাফ স্পোর্টিং ক্লাব&nbsp;এর যাত্রা ২০১০ইং থেকে ২০২৪ইং সন পর্যন্ত ১৪ বছর পূর্ণ হয়।&nbsp;১৪ বছর পূর্তি উপলক্ষে&nbsp;ফ্রেন্ডস স্টাফ স্পোর্টিং ক্লাবের সদস্যরা মিলে কেক কাটার মধ্যদিয়ে&nbsp;অনুষ্ঠান উদযাপন করে।</p>', '2024-10-17 20:16:09', '2024-10-17 20:16:09'),
(151, '2024-10-11', 1, 1, NULL, 'দুর্গাপূজার কার্যক্রমে খোঁজ খবর ও কুশল বিনিময়ে মেম্বার ফারুক আহমেদ', '1729183228Umonpur purbo para visit for puja.webp', NULL, '<p><strong>দুর্গাপূজা</strong>&nbsp;বা দুর্গোৎসব হল দেবী দুর্গার পূজাকে কেন্দ্র করে ভারতীয় উপমহাদেশে প্রচলিত একটি হিন্দু উৎসব। এটি সারা বিশ্বে হিন্দু সম্প্রদায়ের দ্বারা পালিত হয়, তবে ভারতের পশ্চিমবঙ্গ, আসাম, ওড়িশা, বিহার, ত্রিপুরা, ঝাড়খণ্ড, উত্তর প্রদেশ (পূর্বাঞ্চল) এবং বাংলাদেশে ঐতিহ্যগত বিশেষভাবে উদযাপিত হয়।<br />\r\n<br />\r\nদুর্গাপূজার কার্যক্রমের খোঁজ খবর ও কুশল বিনিময় করতে উমনপুর গ্রামের পূর্বপাড়ায় অত্র ওয়ার্ডের মেম্বার ফারুক আহমেদসহ গ্রামের ময়মুরুব্বি ও যুব সমাজ মিলে পরিদর্শন করেন।</p>', '2024-10-17 20:40:28', '2024-10-17 22:12:25'),
(152, '2024-10-16', 1, 2, NULL, 'চিকনাগুল ইউনিয়ন স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্রে আগামী তিন দিন (শনি, রবি ও সোম) ডাক্তার সেবা বন্ধ থাকিবে।', '', NULL, '<p>চিকনাগুল ইউনিয়ন স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্রে সেবাগ্রহীতারদের সদয় অবগতির জন্য জানানো যাচ্ছে যে, আগামী শনিবার ১৯/১০/২০২৪ইং থেকে ২১/১০/২০২৪ইং ( শনি,রবি, সোম) এই তিন দিন উমনপুর হাসপাতালে ডাক্তার সাহেব সেবা দান করবেন না, এই তিনদিন তিনি চারিকাটা ইউনিয়ন স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্রে অতিরিক্ত দায়িত্ব পালন করবেন। সপ্তাহে ৩ দিন ( মঙ্গল, বুধ, ও বৃহস্পতিবার যথারীতি দায়িত্ব পালন করবেন।</p>\r\n\r\n<p>ডা. জাবেদ আহমদ</p>\r\n\r\n<p>চিকনাগুল ইউনিয়ন স্বাস্থ্য ও পরিবার কল্যাণ কেন্দ্র।</p>', '2024-10-17 21:03:23', '2024-10-18 16:56:25'),
(153, '2024-10-18', 1, 2, NULL, 'আজ শুক্রবার উমনপুর মাদ্রসার মাঠে শোকরিয়া সভায় সকলকে উপস্থিত থাকার অনুরোধ করা হইলো।', '', NULL, '<p>উমনপুর গ্রামের যুব সমাজের উদ্যেগে আজ ১৮/১০/২০২৪ইং&nbsp; শুক্রবার&nbsp;রাত উমনপুর মাদ্রাসার মাঠে শোকরিয়া সভার আয়োজন করা হয়েছে।&nbsp;উক্ত সভায় গ্রামের সমসাময়িক বিষয়গুলো নিয়ে গুরুত্বপূর্ণ সিদ্ধান্ত গ্রহন করা হইবে তাই&nbsp; গ্রামের সকল পাড়া-মহল্লার যুবসমাজের উপস্থিতি একান্ত কাম্য।&nbsp;<br />\r\n<br />\r\nসময় রাত&nbsp;৭ঃ৩০ মিনিটে সবাইকে&nbsp;মাদ্রাসার মাঠে উপস্থিত থাকার জন্যে অনুরোধ করা হইল।</p>', '2024-10-18 15:17:00', '2024-10-18 15:23:30'),
(154, '2024-11-07', 1, 2, NULL, 'উমনপুর পাহাড় মসজিদ শুভ উদ্বোধনে গ্রামের সকলকে উপস্থিত থাকার অনুরোধ করা হইল', '', NULL, '<p>&nbsp;আসছে আগামীকাল শুক্রবার উমনপুর পাহাড় মসজিদের শুভ উদ্বোধন করা হবে। তাই উমনপুর গ্রামের ছোট-বড় সকল মুসল্লিয়ান দের উপস্থিত থাকার অনুরোধ করা হইল ।</p>', '2024-11-09 11:43:32', '2024-11-09 12:03:53'),
(155, '2024-11-08', 1, 1, NULL, 'উমনপুর পাহাড় মসজিদের শুভ উদ্বোধন আজ', '173113507992F4CDC6-4858-4B08-A0A9-C44A3D3F6547.jpeg', NULL, '<p>আজ শুক্রবার জুম্মার নামাজ পর উমনপুর পাহাড় মসজিদের শুভ উদ্বোধন করা হয়। উদ্বোধন কালে গনমান্য আলেম উলামায়ের উপস্তিতির মাধ্যমে দিনি ওয়াজ নসিয়তের মধ্যে দিয়ে উদ্বোধনের কার্যক্রম সম্পন্ন হয় এবং জামায়াতে নামাজ আদায় হয়।</p>', '2024-11-09 11:51:19', '2024-11-09 11:51:19'),
(156, '2024-11-09', 1, 1, NULL, 'শোক সংবাদ', '17311355298153F6B9-6522-42CF-A87F-B7EF96CD4070.jpeg', NULL, '<p>উমনপুর নিবাসী&nbsp;জনাব নঈম উল্লাহ (কলিম) সাহেব আর আমাদের মাঝে নেই।</p>\r\n\r\n<p>&quot;ইন্নালিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন&quot;।</p>\r\n\r\n<p>তিনি পেশাগত জীবনে একজন গাড়ি চালক ও ব্যবসায়ী ছিলেন। আমরা মরহুমের আত্মার মাগফিরাত কামনা করি ।&nbsp;আমিন 🤲</p>\r\n\r\n<p>মরহুমের জানাজার নামাজ আজ&nbsp;বাদ আছর হরিপুর বাজার মাদ্রাসা মাঠে অনুষ্ঠিত হইবে।</p>', '2024-11-09 11:58:49', '2024-11-09 14:45:35'),
(157, '2024-11-20', 1, 5, NULL, 'বজ্রপাত হতে নিজেকে রক্ষার মহড়া', '17321907354CBD28E6-DAAB-488B-BC95-D1A6993FFD29.jpeg', NULL, '<p>বজ্রপাত সম্পর্কে সচেতন হওয়া ও বজ্রপাত হতে নিজেকে রক্ষার মহড়া বিদ্যালয়ে অনুষ্ঠিত হয়। মহড়া চলাকালীন সময়ে &nbsp;উপস্থিত ছিলেন, এসো শিখি কার্যক্রমের বিধান স্যার ও স্কুলের শিক্ষক মন্ডলীগ্ণ।</p>', '2024-11-21 17:05:35', '2024-11-21 17:05:35'),
(158, '2024-12-27', 1, 1, NULL, 'শোক সংবাদ', '17356495149B671366-77F5-4567-AD01-0A7850DBD01D.jpeg', NULL, '<p>উমনপুর পাহাড় নিবাসী জনাব লালই সাহেবের মা ও<br />\r\nমরহুম আব্দুল গফুর &nbsp;সাহেবের সহধর্মিণী ইন্তেকাল হইয়াছেন।&nbsp;</p>\r\n\r\n<p>&quot;ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন&quot;&nbsp;</p>\r\n\r\n<p>মরহুমার জানাজা আজ বাদ এশা উমনপুর জামে মসজিদে অনুষ্ঠিত হইবে। এতে আপনাদের উপস্তিতি ও দোয়া কামনাকরি।</p>', '2024-12-31 17:51:54', '2024-12-31 17:51:54'),
(159, '2024-12-31', 1, 1, NULL, '৩০ জানুয়ারী স্মার্ট কার্ড সংগ্রহের দিন', '173564967523648A3C-8767-4152-9B92-CA3222992F6C.jpeg', NULL, '<p>উমনপুর গ্রামের ভোটারদের জানানো যাচ্ছে যে, ৩০ জানুয়ারী ২০২৪ইং তারিখে চিকনাগুল ইউনিয়ন থেকে স্মার্ট কার্ড সংগ্রহ করার অনুরোধ রইলো।</p>', '2024-12-31 17:54:35', '2025-01-01 00:13:18'),
(161, '2025-01-10', 1, 1, NULL, 'মেধাবৃত্তি নিয়ে এলো বিদ্যালয়ের শিক্ষার্থীরা', '1736535377scolarship.webp', NULL, '<p>আলহামদুলিল্লাহ!<br />\r\nউমনপুর সরকারি প্রাথমিক বিদ্যালয়ের শিক্ষার্থীরা আইডিয়াল মেধা বৃত্তি পরীক্ষায় ২টি সাধারণ বৃত্তি সহ বিভিন্ন শিক্ষা প্রতিষ্ঠান থেকে আরো ৪টি মেধা বৃত্তি পেয়েছে। উক্ত ৬জন বৃত্তিপ্রাপ্ত শিক্ষার্থীদের বিদ্যালয়ের পক্ষথেকে অভিনন্দন।<br />\r\n<br />\r\nঅভিভাবকগণদের প্রতি দৃষ্টি আকর্ষণ করি এই যে, আপনার সন্তানদের বই পুস্তকের দিকে মনযোগী করে তুলুন এবং খেলাধুলা ও বিভিন্ন ইভেন্টে অংশগ্রহনের জন্যে উৎসাহিত করুন।<br />\r\n<br />\r\nআর অযথা সময় অপচয় করা থেকে আপনার সন্তানকে বিরত রাখুন। প্রয়োজনে সন্তানের প্রতি খেয়াল রাখবেন।<br />\r\n<br />\r\nধন্যবাদ</p>', '2025-01-10 23:51:43', '2025-01-11 13:08:02'),
(162, '2025-01-07', 1, 2, NULL, 'গ্রামের যুব সমাজ ও ছাত্র সমাজকে নিয়ে এক পরামর্শ সভার ডাক দেওয়া হইয়াছে সকলকে উপস্থিত থাকার অনুরোধ করা হইল।', '', NULL, '<p>আসছে আগামী কাল ০৮/০১/২০২৫ইং রোজ বুধবার বাদ এশার নামাজের পর উমনপুর মাদ্রাসা হল রুমে গ্রামের সকল যুব সমাজ ও ছাত্র সমাজদের নিয়ে এক পরামর্শ সভার আয়োজন করা হয়েছে। উক্ত পরামর্শ সভায় গ্রামের ছোট বড় সবাই উপস্থিত থাকার অনুরোধ করা হইল।</p>', '2025-01-14 12:01:08', '2025-01-14 12:03:42'),
(163, '2025-01-11', 1, 1, NULL, 'গ্রামে বেড়েছে  গরু চুরি', '1736840658Goru Churi_1.jpg', NULL, '<p>উমনপুর গ্রামের স্থায়ী বাসিন্দা মাওলানা আব্দুল হালিম সাহেবের দুইটি গরু গতকালক রাত ১:৩০ মিনিট পর থেকে চুরচক্র জনাব আব্দুল হালিম সাবের বাড়ী নজরে রাখে তার পর রাত ২ঃ৩০ মিনিটের পর থেকে চুর তার প্ল্যান বাস্তবায়িত করার লক্ষে একশনে নেমে পড়ে&nbsp; ঠিক ৩ঃ১০ মিনিটে বাচ্ছা সহ একটি গাভী ৩ জন চুর ২টি গরু তুলে নিয়ে যায়। ভিডিও লিঙ্কঃ&nbsp;<a href=\"https://youtu.be/T6CFDwHNFHc\">https://youtu.be/T6CFDwHNFHc</a>&nbsp;&nbsp;&hellip; এছাড়াও কায়েসুল ইসলাম সাহেবর ৩টি গরু চুরি হয়ার কথা জানিয়েছেন। চুরকে ধরতে সবাই এগিয়ে আসুন এবং উমনপুর গ্রামকে একটি চুরমুক্ত গ্রাম হিসেবে দেখতে সকলের ভুমিকা অপরিসীম।</p>\r\n\r\n<p>বিঃদ্রঃ যে বা যারা চুরকে ধরিয়ে দিতে পারবেন তাদেরকে পুরস্কৃত করা হবে।</p>', '2025-01-14 12:44:18', '2025-01-21 05:18:05'),
(164, '2025-01-13', 1, 2, NULL, 'আগামীকাল টার্নিং এর দোকানে জরুরী পরামর্শ সভায় সকলকে উপস্থিত থাকার অনুরোধ করা হইল', '', NULL, '<p>আগামী কাল ১৪/০১/২০২৫ইং মঙ্গলবার বাদ এশা ট্রানিং এর দোকানে প্রতিবারের মতো এবারও উমনপুর ওয়াজ মাহফিলের ব্যবস্থা করা হয়েছে উক্ত ওয়াজ মাহফিলের আয়োজনে আগামীকাল একটি জরুরী পরামর্শ সভায়র আয়োজন করা হইয়াছে। উমনপুর গ্রামের ছোট বড় সবাইকে উপস্থিত থাকার জন্য বিশেষভাবে অনুরোধ করা হইল।</p>', '2025-01-14 13:37:26', '2025-01-14 13:38:22'),
(165, '2025-01-16', 1, 1, NULL, 'শোক সংবাদ', '1737054312ShukSongbad_1.jpeg', NULL, '<p>উমনপুর রংগাইরবাড়ি নিবাসী জনাব শামসুল ইসলাম পাখি দুপুরে ইন্তেকাল হইয়াছেন।&nbsp;</p>\r\n\r\n<p>&quot;ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন&quot;&nbsp;</p>\r\n\r\n<p>মরহুমের জানাজা আজ বাদ এশা হরিপুর বাজার মাদ্রাসার মাঠে অনুষ্ঠিত হইবে। এতে আপনাদের উপস্তিতি ও দোয়া কামনাকরি।</p>', '2025-01-17 00:05:12', '2025-01-17 00:06:14'),
(166, '2025-01-18', 1, 1, NULL, 'স্মার্ট কার্ড সংগ্রহের দিন ২৫ জানুয়ারী ২০২৫ইং', '1737180912Smart Card umonpur.jpg', NULL, '<p>উমনপুর গ্রামের ভোটারদের জানানো যাচ্ছে যে, ৩০ জানুয়ারী ২০২৪ইং তারিখ পরিবর্তন করে ২৫ জানুয়ারী ২০২৫ইং এম আহমদ পাবলিক স্কুল এন্ড কলেজ থেকে স্মার্ট কার্ড সংগ্রহ করার জন্যে অনুরোধ করা হইলো।</p>', '2025-01-18 11:15:12', '2025-01-18 11:15:12'),
(167, '2025-01-21', 1, 2, NULL, 'পহেলা ফেব্রুয়ারি তাফসিরুল কোরআন মাহফিলে সবাই উপস্থিত থাকার আহ্ববান করা হচ্ছে', '', NULL, '<p>সম্মানিত উমনপুর গ্রামবাসী আসছে আগামী পহেলা ফেব্রুয়ারী ২০২৫ইং শনিবার উমনপুর জামে মসজীদে বেলা দুপুর ১২টা হতে রাত ১০টা পর্জন্ত মুর্দেগানের মাগফিরাত কামনায় এবং উমনপুর গ্রামের জামে মসজিদে এসির ব্যবস্থার &nbsp;জন্যে ওয়াজ মাহফিলের আয়োজন করা হয়েছে। উক্ত ওয়াজ মাহফিলে আপনাদের উপস্থিতি, দোয়া ও আর্থিক সহযোগিতা কামনা করি।</p>', '2025-01-21 04:49:15', '2025-01-21 04:50:23');
