INSERT INTO `testimonials` (`id`, `name`, `image`, `designation`, `message`, `user_id`, `member_id`, `created_at`, `updated_at`) VALUES
(6, 'সায়েম আহমদ', '1737395818Sayem.jpg', 'সফটওয়্যার ইঞ্জিনিয়ার', 'উমনপুর একটি আদর্শ গ্রামের নাম। এই গ্রাম আমার জন্মভূমি। উমনপুর গ্রাম আমার জন্মভূমি হওয়ায় আমি নিজেকে ধন্য মনে করি। উমনপুর গ্রাম একটি ডিজিটাল ও নেটিজেন গ্রাম।\r\n\r\nউমনপুর গ্রামের  মুরুব্বিয়ান, যুব সমাজ ও ছাত্র সমাজ সবাই সচেতন নাগরিক। সকলের সহযোগিতায় আজকের এই ওয়েবসাইট অনলাইনে দৃশ্যমান। আমি নিজেকে ধন্য মনেকরি এই যে আমার গ্রামের উদ্দেশ্যে ওয়েবসাইট নির্মাণ করতে পারায়। ভবিষ্যতে ক্রিয়েটিভ কিছু নিয়ে আসার স্বপ্ন আছে, যদি সুযোগ থাকে। আমি আশাবাদী উমনপুর গ্রামের ইতিহাস ঐতিহ্য ফোটে উঠবে এই প্লাটফর্মে । \r\n\r\n সকলের প্রতি শুভকামনা।', 1, NULL, '2022-11-21 07:55:33', '2025-01-20 22:56:58'),
(14, 'মোহাম্মদ মন্তাজ আলী', '1737410127Mohammod Montaj Ali.jpg', 'ব্যবসায়ী', 'উমনপুর গ্রাম একটি আদর্শ ও ডিজিটাল গ্রাম। জন্মগত ভাবে আমি একজন উমনপুর গ্রামের নাগরিক হওয়ায় নিজেকে ধন্য মনেকরি। উমনপুর গ্রামের সমাজ ব্যবস্তা খুবী চমৎকার। আমাদের গ্রামে নদী, নালা, খাল, বিল ও পাহাড় নিয়ে উমনপুর গ্রামের প্রকৃতি অনেক চমৎকার।', 95, NULL, '2025-01-21 02:55:27', '2025-01-21 02:55:27'),
(15, 'মইনুল হোসেইন', '1737411537member_1692938362.jpg', 'সরকারী কর্মকর্তা', 'উমনপুর একটি আদর্শ ও ডিজিটাল গ্রাম। এই গ্রামের সুনাম বিস্তৃত। আমাদের ডিজিটাল গ্রামের সফটওয়্যার পরবর্তী জেনারেশনের একটি অনুপ্রেরণা হয়ে থাকবে।', 55, NULL, '2025-01-21 03:18:57', '2025-01-21 03:18:57');
